package handlers

import (
	"database/sql"
	"net/http"
	"sort"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
)

type HiringHandler struct {
	DB               *sql.DB
	EnableFuzzyDedup bool
}

func NewHiringHandler(db *sql.DB, enableFuzzy bool) *HiringHandler {
	return &HiringHandler{DB: db, EnableFuzzyDedup: enableFuzzy}
}

func (h *HiringHandler) CreateJob(c *gin.Context) {
	var req struct {
		Code        string `json:"code"`
		Title       string `json:"title"`
		Description string `json:"description"`
		SiteCode    string `json:"site_code"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
		return
	}
	id := uuid.NewString()
	_, err := h.DB.Exec(`
		INSERT INTO job_postings(id, code, title, description, site_code, created_at)
		VALUES ($1,$2,$3,$4,$5,now())
	`, id, req.Code, req.Title, req.Description, req.SiteCode)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "job create failed", "detail": err.Error()})
		return
	}
	c.JSON(http.StatusCreated, gin.H{"id": id})
}

func (h *HiringHandler) CreateManualApplication(c *gin.Context) {
	var req struct {
		JobID      string `json:"job_id"`
		FullName   string `json:"full_name"`
		Email      string `json:"email"`
		Phone      string `json:"phone"`
		SSN        string `json:"ssn"`
		SourceType string `json:"source_type"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
		return
	}

	identityKey := strings.ToLower(strings.TrimSpace(req.Email)) + "|" + normalizePhone(req.Phone)

	var duplicateID string
	err := h.DB.QueryRow(`
		SELECT candidate_id FROM candidate_identities
		WHERE identity_key = $1
		LIMIT 1
	`, identityKey).Scan(&duplicateID)

	riskScore := 0
	triggers := []string{}
	if err == nil {
		riskScore = 90
		triggers = append(triggers, "exact_identity_match")
	}

	if h.EnableFuzzyDedup {
		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(req.FullName)), "test") {
			riskScore += 10
			triggers = append(triggers, "fuzzy_name_rule")
		}
	}

	candidateID := uuid.NewString()
	applicationID := uuid.NewString()

	tx, err := h.DB.Begin()
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "transaction start failed"})
		return
	}
	defer tx.Rollback()

	_, err = tx.Exec(`
		INSERT INTO candidates(id, full_name, email, phone, ssn_raw, created_at)
		VALUES ($1,$2,$3,$4,$5,now())
	`, candidateID, req.FullName, strings.ToLower(req.Email), normalizePhone(req.Phone), req.SSN)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "candidate create failed", "detail": err.Error()})
		return
	}

	_, err = tx.Exec(`
		INSERT INTO candidate_identities(id, candidate_id, identity_key, created_at)
		VALUES ($1,$2,$3,now())
	`, uuid.NewString(), candidateID, identityKey)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "identity create failed", "detail": err.Error()})
		return
	}

	_, err = tx.Exec(`
		INSERT INTO applications(id, candidate_id, job_id, source_type, stage_code, created_at)
		VALUES ($1,$2,$3,$4,'SCREENING',now())
	`, applicationID, candidateID, req.JobID, normalizeSource(req.SourceType))
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "application create failed", "detail": err.Error()})
		return
	}

	_, err = tx.Exec(`
		INSERT INTO candidate_dedupe_hits(id, candidate_id, risk_score, triggers, created_at)
		VALUES ($1,$2,$3,$4,now())
	`, uuid.NewString(), candidateID, riskScore, strings.Join(triggers, ","))
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "dedupe write failed"})
		return
	}

	if err := tx.Commit(); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "transaction commit failed"})
		return
	}

	c.JSON(http.StatusCreated, gin.H{
		"application_id": applicationID,
		"candidate_id":   candidateID,
		"risk_score":     riskScore,
		"rule_triggers":  triggers,
	})
}

func (h *HiringHandler) ValidatePipeline(c *gin.Context) {
	var req struct {
		Stages []struct {
			Code       string `json:"code"`
			Name       string `json:"name"`
			Terminal   bool   `json:"terminal"`
			Outcome    string `json:"outcome"`
			MinFields  int    `json:"min_required_fields"`
			MaxFields  int    `json:"max_required_fields"`
			OrderIndex int    `json:"order_index"`
		} `json:"stages"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
		return
	}
	if len(req.Stages) < 3 || len(req.Stages) > 20 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "stage count must be between 3 and 20"})
		return
	}

	seen := map[string]bool{}
	terminalSuccess := 0
	terminalFailure := 0
	for _, s := range req.Stages {
		code := strings.TrimSpace(strings.ToUpper(s.Code))
		if code == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "stage code cannot be empty"})
			return
		}
		if seen[code] {
			c.JSON(http.StatusBadRequest, gin.H{"error": "stage codes must be unique", "code": code})
			return
		}
		seen[code] = true

		if s.MinFields > s.MaxFields {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid stage min/max required fields", "code": code})
			return
		}

		if s.Terminal {
			outcome := strings.ToLower(strings.TrimSpace(s.Outcome))
			if outcome == "success" {
				terminalSuccess++
			}
			if outcome == "failure" {
				terminalFailure++
			}
		}
	}
	if terminalSuccess < 1 || terminalFailure < 1 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "pipeline requires at least one success and one failure terminal stage"})
		return
	}

	sort.Slice(req.Stages, func(i, j int) bool {
		return req.Stages[i].OrderIndex < req.Stages[j].OrderIndex
	})

	c.JSON(http.StatusOK, gin.H{"valid": true, "validated_at": time.Now().UTC()})
}

func normalizePhone(in string) string {
	b := strings.Builder{}
	for _, r := range in {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func normalizeSource(source string) string {
	s := strings.TrimSpace(strings.ToUpper(source))
	switch s {
	case "MANUAL", "KIOSK", "CSV":
		return s
	default:
		return "MANUAL"
	}
}

