+		VALUES ($1,$2,$3,$4,$5,'OPEN',1,now())
+	`, id, req.OrderID, tt, strings.ToUpper(req.Priority), req.Description)
+	if err != nil {
+		c.JSON(http.StatusBadRequest, gin.H{"error": "ticket creation failed", "detail": err.Error()})
+		return
+	}
+
+	c.JSON(http.StatusCreated, gin.H{"id": id, "record_version": 1})
+}
+
+func (h *SupportHandler) AddAttachment(c *gin.Context) {
+	ticketID := c.Param("id")
+	var req struct {
+		FileName string `json:"file_name"`
+		MimeType string `json:"mime_type"`
+		SizeMB   int    `json:"size_mb"`
+		Checksum string `json:"checksum"`
+	}
+	if err := c.ShouldBindJSON(&req); err != nil {
+		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
+		return
+	}
+	if req.SizeMB <= 0 || req.SizeMB > 10 {
+		c.JSON(http.StatusBadRequest, gin.H{"error": "attachment exceeds 10MB limit"})
+		return
+	}
+	allowed := map[string]bool{"image/jpeg": true, "image/png": true, "application/pdf": true}
+	if !allowed[strings.ToLower(req.MimeType)] {
+		c.JSON(http.StatusBadRequest, gin.H{"error": "unsupported attachment type"})
+		return
+	}
+
