}

.bg-app {
  background:
    radial-gradient(circle at 10% 10%, #e2ecf8 0%, transparent 28%),
    radial-gradient(circle at 90% 0%, #d6ebe0 0%, transparent 30%),
    var(--bg);
  min-height: 100vh;
}

.text-body {
  color: var(--text);
}

.page-wrap {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: 0 8px 24px rgba(5, 25, 44, 0.08);
}

.auth-card {
  width: 100%;
  max-width: 420px;
}

.title {
  margin: 0;
  font-size: 1.6rem;
}

.subtitle {
  margin-top: 8px;
  color: var(--muted);
}

.stack {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.label {
  font-weight: 600;
}

.input {
  height: 40px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0 10px;
}

.btn,
.ghost-btn {
  min-height: 40px;
  border-radius: 10px;
  cursor: pointer;
  border: none;
  font-weight: 600;
}

.btn {
  background: var(--brand);
  color: #fff;
}

.btn:hover {
  background: var(--brand-strong);
}

.ghost-btn {
  border: 1px solid var(--border);
  background: #fff;
  padding: 0 12px;
}

.error-text {
  color: var(--error);
  min-height: 1rem;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(4px);
  position: sticky;
  top: 0;
}

.topbar-title {
  margin: 0;
  font-size: 1.2rem;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 12px;
  padding: 12px;
