{"patchText": "*** Begin Patch
*** Add File: frontend/ui/static/js/app.js
+(function () {
+  const path = window.location.pathname;
+
+  function saveDraft(key, value) {
+    localStorage.setItem("draft:" + key, JSON.stringify({ value, ts: Date.now() }));
+  }
+
+  function addLog(msg) {
+    const el = document.getElementById("activity-log");
+    if (!el) return;
+    el.textContent = `[${new Date().toISOString()}] ${msg}\n` + el.textContent;
+  }
+
+  async function rpc(url, payload, opts) {
+    const options = opts || {};
+    const headers = {
+      "Content-Type": "application/json",
+    };
+    if (options.auth && localStorage.getItem("access_token")) {
+      headers.Authorization = "Bearer " + localStorage.getItem("access_token");
+    }
+    if (options.idempotency) {
+      headers["Idempotency-Key"] = crypto.randomUUID();
+    }
+    if (options.stepUp && localStorage.getItem("step_up_token")) {
+      headers["X-Step-Up-Token"] = localStorage.getItem("step_up_token");
+    }
+
+    const body = JSON.stringify(payload || {});
+    saveDraft(url, payload || {});
+
+    try {
+      const res = await fetch(url, { method: "POST", headers, body });
+      const json = await res.json().catch(() => ({}));
+      if (!res.ok) throw json;
+      localStorage.removeItem("draft:" + url);
+      return json;
+    } catch (err) {
+      addLog(`Request failed for ${url}. Draft kept.`);
+      throw err;
+    }
+  }
+
+  async function loginFlow(e) {
+    e.preventDefault();
+    const username = document.getElementById("username").value.trim();
+    const password = document.getElementById("password").value;
+    const errorEl = document.getElementById("login-error");
+    errorEl.textContent = "";
+
+    try {
+      const res = await rpc("/rpc/login", { username, password });
+      localStorage.setItem("access_token", res.access_token);
+      localStorage.setItem("refresh_token", res.refresh_token);
+      window.location.href = "/dashboard";
+    } catch (err) {
+      errorEl.textContent = err.error || "Login failed";
+    }
+  }
+
+  async function stepUp(actionClass) {
+    const pw = window.prompt("Re-enter password for sensitive action");
+    if (!pw) return null;
+    const res = await rpc(
+      "/rpc/api/auth/step-up",
+      { password: pw, action_class: actionClass },
+      { auth: true }
+    );
+    localStorage.setItem("step_up_token", res.step_up_token);
+    return res.step_up_token;
+  }
+
+  async function dashboardActions() {
+    const logout = document.getElementById("logout-btn");
+    if (logout) {
+      logout.addEventListener("click", () => {
+        localStorage.clear();
+        window.location.href = "/";
+      });
+    }
+
+    const jobBtn = document.getElementById("create-job-btn");
+    if (jobBtn) {
+      jobBtn.addEventListener("click", async () => {
+        const payload = {
+          code: "JOB-" + Math.floor(Math.random() * 10000),
+          title: "Warehouse Associate",
+          description: "Inbound and cycle count support",
+          site_code: "SITE-A",
+        };
+        const res = await rpc("/rpc/api/hiring/jobs", payload, { auth: true });
+        addLog("Created job: " + res.id);
+      });
+    }
+
+    const ticketBtn = document.getElementById("create-ticket-btn");
+    if (ticketBtn) {
+      ticketBtn.addEventListener("click", async () => {
+        const payload = {
+          order_id: "ORD-" + Math.floor(Math.random() * 100000),
+          ticket_type: "refund_only",
+          priority: "STANDARD",
+          description: "Customer requested refund for non-returnable item",
+        };
+        const res = await rpc("/rpc/api/support/tickets", payload, { auth: true });
+        addLog("Created support ticket: " + res.id);
+      });
+    }
+
+    const reserveBtn = document.getElementById("create-reservation-btn");
+    if (reserveBtn) {
+      reserveBtn.addEventListener("click", async () => {
+        const payload = {
+          order_id: "ORD-" + Math.floor(Math.random() * 100000),
+          sku: "SKU-100",
+          quantity: 5,
+          warehouse: "WH-1",
+          priority: 1,
+          site_code: "SITE-A",
+        };
+        const res = await rpc("/rpc/api/inventory/reservations/order-create", payload, {
+          auth: true,
+          idempotency: true,
+        });
+        addLog("Created reservation: " + res.id);
+      });
+    }
+
+    if (!localStorage.getItem("access_token")) {
+      addLog("No access token. Please login again.");
+    }
+
+    window.addEventListener("online", () => addLog("Network restored"));
+    window.addEventListener("offline", () => addLog("Offline mode; drafts retained"));
+
+    document.addEventListener("keydown", async (e) => {
+      if (e.key === "F9") {
+        await stepUp("refund_approval");
+        addLog("Step-up token refreshed for refund_approval.");
+      }
+    });
+  }
+
+  if (path === "/") {
+    const form = document.getElementById("login-form");
+    if (form) form.addEventListener("submit", loginFlow);
+  }
+
+  if (path === "/dashboard") {
+    dashboardActions();
+  }
+})();
+
*** End Patch"}

