+			return
+		}
+		defer rows.Close()
+
+		ok := false
+		for rows.Next() {
+			var scope string
+			if rows.Scan(&scope) == nil && allowedSet[scope] {
+				ok = true
+				break
+			}
+		}
+		if !ok {
+			c.AbortWithStatusJSON(http.StatusForbidden, gin.H{"error": "scope denied"})
