		"candidate_id":   candidateID,
		"risk_score":     riskScore,
		"rule_triggers":  triggers,
	})
}

func (h *HiringHandler) ValidatePipeline(c *gin.Context) {
	var req struct {
		Stages []struct {
			Code       string `json:"code"`
			Name       string `json:"name"`
			Terminal   bool   `json:"terminal"`
			Outcome    string `json:"outcome"`
			MinFields  int    `json:"min_required_fields"`
			MaxFields  int    `json:"max_required_fields"`
			OrderIndex int    `json:"order_index"`
		} `json:"stages"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
		return
	}
	if len(req.Stages) < 3 || len(req.Stages) > 20 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "stage count must be between 3 and 20"})
		return
	}

	seen := map[string]bool{}
	terminalSuccess := 0
	terminalFailure := 0
	for _, s := range req.Stages {
		code := strings.TrimSpace(strings.ToUpper(s.Code))
		if code == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "stage code cannot be empty"})
			return
		}
		if seen[code] {
			c.JSON(http.StatusBadRequest, gin.H{"error": "stage codes must be unique", "code": code})
			return
		}
		seen[code] = true

		if s.MinFields > s.MaxFields {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid stage min/max required fields", "code": code})
			return
		}

		if s.Terminal {
			outcome := strings.ToLower(strings.TrimSpace(s.Outcome))
			if outcome == "success" {
				terminalSuccess++
			}
			if outcome == "failure" {
				terminalFailure++
			}
		}
	}
	if terminalSuccess < 1 || terminalFailure < 1 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "pipeline requires at least one success and one failure terminal stage"})
		return
	}

	sort.Slice(req.Stages, func(i, j int) bool {
		return req.Stages[i].OrderIndex < req.Stages[j].OrderIndex
	})

	c.JSON(http.StatusOK, gin.H{"valid": true, "validated_at": time.Now().UTC()})
}

func normalizePhone(in string) string {
	b := strings.Builder{}
	for _, r := range in {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func normalizeSource(source string) string {
	s := strings.TrimSpace(strings.ToUpper(source))
	switch s {
	case "MANUAL", "KIOSK", "CSV":
		return s
	default:
		return "MANUAL"
	}
}

