+func (h *InventoryHandler) ReleaseReservation(c *gin.Context) {
+	id := c.Param("id")
+	var req struct {
+		ReasonCode string `json:"reason_code"`
+	}
+	_ = c.ShouldBindJSON(&req)
+
+	tx, err := h.DB.BeginTx(context.Background(), nil)
+	if err != nil {
+		c.JSON(http.StatusInternalServerError, gin.H{"error": "transaction failed"})
+		return
+	}
+	defer tx.Rollback()
+
+	var sku, wh string
+	var reserved, confirmed int
+	err = tx.QueryRow(`SELECT sku, warehouse_code, reserved_qty, confirmed_qty FROM inventory_reservations WHERE id=$1 FOR UPDATE`, id).Scan(&sku, &wh, &reserved, &confirmed)
+	if err != nil {
+		c.JSON(http.StatusNotFound, gin.H{"error": "reservation not found"})
+		return
+	}
+
+	released := reserved - confirmed
+	_, err = tx.Exec(`UPDATE inventory_reservations SET released_qty=$2, status='RELEASED', updated_at=now() WHERE id=$1`, id, released)
+	if err != nil {
+		c.JSON(http.StatusBadRequest, gin.H{"error": "reservation release failed"})
+		return
+	}
+	_, _ = tx.Exec(`UPDATE inventory_balances SET reserved=reserved-$3, updated_at=now() WHERE warehouse_code=$1 AND sku=$2`, wh, sku, released)
+	_, _ = tx.Exec(`INSERT INTO reservation_events(id, reservation_id, event_type, quantity, reason_code, created_at) VALUES ($1,$2,'RELEASED',$3,$4,now())`, uuid.NewString(), id, released, req.ReasonCode)
+
+	if err := tx.Commit(); err != nil {
+		c.JSON(http.StatusInternalServerError, gin.H{"error": "commit failed"})
+		return
+	}
+
+	c.JSON(http.StatusOK, gin.H{"released": true, "at": time.Now().UTC()})
+}
