(function () {
  const path = window.location.pathname;
  const RETRY_KEY = "offline:retry_queue";

  function loadQueue() {
    try {
      return JSON.parse(localStorage.getItem(RETRY_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function saveQueue(items) {
    localStorage.setItem(RETRY_KEY, JSON.stringify(items));
    updateQueueState();
  }

  function enqueueRetry(req) {
    const q = loadQueue();
    q.push(req);
    saveQueue(q);
  }

  function saveDraft(key, value) {
    localStorage.setItem("draft:" + key, JSON.stringify({ value, ts: Date.now() }));
  }

  function addLog(msg) {
    const el = document.getElementById("activity-log");
    if (!el) return;
    el.textContent = `[${new Date().toISOString()}] ${msg}\n` + el.textContent;
  }

  function updateQueueState() {
    const qEl = document.getElementById("queue-state");
    if (qEl) qEl.textContent = `Retry queue: ${loadQueue().length}`;
  }

  function updateNetworkState() {
    const nEl = document.getElementById("network-state");
    if (!nEl) return;
    nEl.textContent = "Network: " + (navigator.onLine ? "online" : "offline");
  }

  function parseJwt(token) {
    try {
      const payload = token.split(".")[1];
      return JSON.parse(atob(payload.replace(/-/g, "+").replace(/_/g, "/")));
    } catch {
      return {};
    }
  }

  function updateSessionLabel() {
    const el = document.getElementById("session-user");
    if (!el) return;
    const token = localStorage.getItem("access_token");
    if (!token) {
      el.textContent = "No active session";
      return;
    }
    const claims = parseJwt(token);
    el.textContent = `User: ${claims.username || "unknown"}`;
  }

  async function rpc(url, payload, opts) {
    const options = opts || {};
    const headers = {
      "Content-Type": "application/json",
    };
    if (options.auth && localStorage.getItem("access_token")) {
      headers.Authorization = "Bearer " + localStorage.getItem("access_token");
    }
    if (options.idempotency) {
      headers["Idempotency-Key"] = crypto.randomUUID();
    }
    if (options.stepUp && localStorage.getItem("step_up_token")) {
      headers["X-Step-Up-Token"] = localStorage.getItem("step_up_token");
    }

    const body = JSON.stringify(payload || {});
    saveDraft(url, payload || {});

    try {
      const res = await fetch(url, { method: "POST", headers, body });
      const json = await res.json().catch(() => ({}));
      if (!res.ok) {
        if (res.status === 409 && options.conflictPrompt) {
          return await resolveConflict(options.conflictPrompt, payload, json);
        }
        throw { status: res.status, ...json };
      }
      localStorage.removeItem("draft:" + url);
      return json;
    } catch (err) {
      addLog(`Request failed for ${url}. Draft kept.`);
      if (options.retryable) {
        enqueueRetry({ url, payload, opts: { ...options, retryable: false } });
      }
      throw err;
    }
  }

  async function resolveConflict(endpoint, payload, serverErr) {
    const choice = window.prompt(
      "Conflict detected. Type: merge, overwrite, or discard",
      "merge"
    );
    const mode = (choice || "discard").toLowerCase();
    if (mode === "discard") {
      return { discarded: true, reason: serverErr.error || "conflict discarded" };
    }
    return rpc(endpoint, {
      mode,
      current_version: serverErr.current_version || payload.record_version || 1,
      expected_version: payload.record_version || 1,
      description: payload.description || "",
    }, { auth: true });
  }

  async function flushRetryQueue() {
    if (!navigator.onLine) return;
    const queue = loadQueue();
    if (queue.length === 0) return;

    const remaining = [];
    for (const item of queue) {
      try {
        await rpc(item.url, item.payload, item.opts || {});
        addLog(`Retried and succeeded: ${item.url}`);
      } catch {
        remaining.push(item);
      }
    }
    saveQueue(remaining);
  }

  async function loginFlow(e) {
    e.preventDefault();
    const username = document.getElementById("username").value.trim();
    const password = document.getElementById("password").value;
    const errorEl = document.getElementById("login-error");
    errorEl.textContent = "";

    try {
      const res = await rpc("/rpc/login", { username, password });
      localStorage.setItem("access_token", res.access_token);
      localStorage.setItem("refresh_token", res.refresh_token);
      window.location.href = "/dashboard";
    } catch (err) {
      errorEl.textContent = err.error || "Login failed";
    }
  }

  async function stepUp(actionClass) {
    const pw = window.prompt("Re-enter password for sensitive action");
    if (!pw) return null;
    const res = await rpc("/rpc/api/auth/step-up", { password: pw, action_class: actionClass }, { auth: true });
    localStorage.setItem("step_up_token", res.step_up_token);
    return res.step_up_token;
  }

  async function dashboardActions() {
    updateSessionLabel();
    updateNetworkState();
    updateQueueState();

    const logout = document.getElementById("logout-btn");
    if (logout) {
      logout.addEventListener("click", () => {
        localStorage.clear();
        window.location.href = "/";
      });
    }

    const jobBtn = document.getElementById("create-job-btn");
    if (jobBtn) {
      jobBtn.addEventListener("click", async () => {
        const payload = {
          code: "JOB-" + Math.floor(Math.random() * 10000),
          title: "Warehouse Associate",
          description: "Inbound and cycle count support",
          site_code: "SITE-A",
        };
        const res = await rpc("/rpc/api/hiring/jobs", payload, { auth: true, retryable: true });
        addLog("Created job: " + res.id);
      });
    }

    const kioskBtn = document.getElementById("create-kiosk-app-btn");
    if (kioskBtn) {
      kioskBtn.addEventListener("click", async () => {
        const payload = {
          job_id: prompt("Job ID", "") || "",
          full_name: "Kiosk Candidate",
          email: `candidate${Math.floor(Math.random() * 9000)}@example.com`,
          phone: "5551112233",
          ssn: "123-45-6789",
        };
        const res = await rpc("/rpc/api/hiring/applications/kiosk", payload, { auth: true, retryable: true });
        addLog("Created kiosk app: " + res.application_id + " severity=" + res.severity);
      });
    }

    const ticketBtn = document.getElementById("create-ticket-btn");
    if (ticketBtn) {
      ticketBtn.addEventListener("click", async () => {
        const payload = {
          order_id: "ORD-1001",
          ticket_type: "return_and_refund",
          priority: "HIGH",
          description: "Customer requested return for delivered order",
          business_site: "SITE-A",
        };
        const res = await rpc("/rpc/api/support/tickets", payload, {
          auth: true,
          retryable: true,
          conflictPrompt: `/rpc/api/support/tickets/${payload.order_id}/conflict-resolve`,
        });
        localStorage.setItem("last_ticket_id", res.id);
        addLog(`Created support ticket: ${res.id} due=${res.sla_due_at}`);
      });
    }

    const loadTicketBtn = document.getElementById("load-ticket-btn");
    if (loadTicketBtn) {
      loadTicketBtn.addEventListener("click", async () => {
        const id = localStorage.getItem("last_ticket_id") || prompt("Ticket ID") || "";
        if (!id) return;
        const res = await fetch(`/rpc/api/support/tickets/${id}`, {
          headers: { Authorization: "Bearer " + localStorage.getItem("access_token") },
        });
        const json = await res.json();
        if (!res.ok) throw json;
        addLog(`Ticket ${id}: SLA remaining ${json.sla_seconds}s priority=${json.priority}`);
      });
    }

    const reserveBtn = document.getElementById("create-reservation-btn");
    if (reserveBtn) {
      reserveBtn.addEventListener("click", async () => {
        const payload = {
          order_id: "ORD-" + Math.floor(Math.random() * 100000),
          sku: "SKU-100",
          quantity: 5,
          site_code: "SITE-A",
        };
        const res = await rpc("/rpc/api/inventory/reservations/order-create", payload, {
          auth: true,
          idempotency: true,
          retryable: true,
        });
        addLog(`Created reservation: ${res.id} warehouse=${res.warehouse}`);
      });
    }

    const balBtn = document.getElementById("inventory-balance-btn");
    if (balBtn) {
      balBtn.addEventListener("click", async () => {
        const res = await fetch("/rpc/api/inventory/balances?site=SITE-A", {
          headers: { Authorization: "Bearer " + localStorage.getItem("access_token") },
        });
        const json = await res.json();
        if (!res.ok) throw json;
        const low = (json.balances || []).filter((b) => b.low_stock_alert).length;
        addLog(`Inventory balances loaded. low-stock warnings=${low}`);
      });
    }

    const crawlerBtn = document.getElementById("run-crawler-btn");
    if (crawlerBtn) {
      crawlerBtn.addEventListener("click", async () => {
        const res = await rpc("/rpc/api/compliance/crawler/run", {}, { auth: true, retryable: true });
        addLog(`Crawler run indexed=${res.indexed} queued=${res.queued}`);
      });
    }

    const retentionBtn = document.getElementById("retention-status-btn");
    if (retentionBtn) {
      retentionBtn.addEventListener("click", async () => {
        const res = await fetch("/rpc/api/compliance/retention/jobs", {
          headers: { Authorization: "Bearer " + localStorage.getItem("access_token") },
        });
        const json = await res.json();
        if (!res.ok) throw json;
        addLog(`Retention due: rejected=${json.rejected_candidates_due}, support=${json.support_records_due}`);
      });
    }

    if (!localStorage.getItem("access_token")) {
      addLog("No access token. Please login again.");
    }

    window.addEventListener("online", async () => {
      updateNetworkState();
      addLog("Network restored");
      await flushRetryQueue();
    });
    window.addEventListener("offline", () => {
      updateNetworkState();
      addLog("Offline mode; drafts retained");
    });

    document.addEventListener("keydown", async (e) => {
      if (e.key === "F9") {
        await stepUp("refund_approval");
        addLog("Step-up token refreshed for refund_approval.");
      }
    });

    setInterval(flushRetryQueue, 15000);
  }

  if (path === "/") {
    const form = document.getElementById("login-form");
    if (form) form.addEventListener("submit", loginFlow);
  }

  if (path === "/dashboard") {
    dashboardActions();
  }
})();

