		var at time.Time
		if err := rows.Scan(&eventType, &from, &to, &details, &at); err == nil {
			out = append(out, gin.H{"event_type": eventType, "from": from, "to": to, "details": details, "at": at})
		}
	}
	c.JSON(http.StatusOK, gin.H{"events": out})
