	})

	for _, st := range stages {
		_, err := tx.Exec(`
			INSERT INTO pipeline_stages(id, template_id, code, name, order_index, terminal, outcome, required_fields)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
