func (s *HiringService) Transition(input hiring.TransitionInput, actorID string) error {
	var required string
	err := s.DB.QueryRow(`
		SELECT pt.required_fields
		FROM applications a
		JOIN pipeline_transitions pt ON pt.template_id=a.pipeline_template_id
		WHERE a.id=$1 AND pt.from_stage_code=$2 AND pt.to_stage_code=$3
	`, input.ApplicationID, strings.ToUpper(input.FromStage), strings.ToUpper(input.ToStage)).Scan(&required)
	if err != nil {
		return errors.New("invalid stage transition")
	}

	if required != "" {
		for _, f := range strings.Split(required, ",") {
			k := strings.TrimSpace(f)
			if k == "" {
				continue
			}
			if strings.TrimSpace(input.Provided[k]) == "" {
				return fmt.Errorf("required field missing: %s", k)
			}
		}
	}

	tx, err := s.DB.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	_, err = tx.Exec(`UPDATE applications SET stage_code=$2, updated_at=now() WHERE id=$1`, input.ApplicationID, strings.ToUpper(input.ToStage))
	if err != nil {
		return err
	}
	_, err = tx.Exec(`
		INSERT INTO application_pipeline_events(id, application_id, actor_id, from_stage_code, to_stage_code, event_type, details)
		VALUES ($1,$2,$3,$4,$5,'TRANSITION',$6::jsonb)
	`, uuid.NewString(), input.ApplicationID, actorID, strings.ToUpper(input.FromStage), strings.ToUpper(input.ToStage), toJSON(input.Provided))
	if err != nil {
		return err
	}

	return tx.Commit()
}

func maxSeverity(a, b hiring.BlockSeverity) hiring.BlockSeverity {
	r := map[hiring.BlockSeverity]int{hiring.SeverityInfo: 1, hiring.SeverityWarn: 2, hiring.SeverityBlock: 3}
	if r[b] > r[a] {
		return b
	}
	return a
}

func toBool(v any) bool {
	s := strings.ToLower(strings.TrimSpace(fmt.Sprint(v)))
	return s == "true" || s == "1" || s == "yes"
}

func toInt(v any) int {
	var x int
	fmt.Sscan(fmt.Sprint(v), &x)
	return x
}

func prefix(s string) string {
	x := strings.TrimSpace(s)
	if len(x) > 4 {
		return x[:4]
	}
	return x
}

func onlyDigits(in string) string {
	b := strings.Builder{}
	for _, r := range in {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func toJSON(m map[string]string) string {
	parts := make([]string, 0, len(m))
	for k, v := range m {
		parts = append(parts, fmt.Sprintf("\"%s\":\"%s\"", escape(k), escape(v)))
	}
	sort.Strings(parts)
	return "{" + strings.Join(parts, ",") + "}"
}

func escape(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	return s
}

