            mode: "merge",
            current_version: 1,
            expected_version: 0,
            description: "Client-side merge test",
          }, { auth: true });
          addLog(`Conflict flow endpoint validated for ticket ${res.id}`);
        } catch {
          addLog(`Conflict flow attempted for ticket ${res.id}`);
        }
      });
