func (h *HiringHandler) GetPipelineEvents(c *gin.Context) {
	id := c.Param("id")
	rows, err := h.DB.Query(`
		SELECT event_type, from_stage_code, to_stage_code, details::text, created_at
		FROM application_pipeline_events
		WHERE application_id=$1
