func (h *HiringHandler) createApplication(c *gin.Context, source string) {
	var req struct {
		JobID     string `json:"job_id"`
		FullName  string `json:"full_name"`
		Email     string `json:"email"`
		Phone     string `json:"phone"`
		SSN       string `json:"ssn"`
		StageCode string `json:"stage_code"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid payload"})
		return
	}

	identityKey := strings.ToLower(strings.TrimSpace(req.Email)) + "|" + normalizePhone(req.Phone)
	risk, dupTriggers, _ := h.Svc.ScoreDuplicate(identityKey, req.FullName)
	sev, blockTriggers, err := h.Svc.EvaluateBlocklist(req.Email, req.FullName, risk > 0)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "blocklist evaluation failed"})
		return
	}

	if sev == hiring.SeverityBlock {
		c.JSON(http.StatusForbidden, gin.H{
			"error":       "candidate blocked by policy",
			"severity":    string(sev),
			"block_rules": blockTriggers,
		})
		return
	}

	stage := strings.ToUpper(strings.TrimSpace(req.StageCode))
	if stage == "" {
		stage = "SCREENING"
	}

	encSSN, err := h.PII.Encrypt(req.SSN)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to encrypt sensitive data"})
		return
	}

	tx, err := h.DB.Begin()
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "transaction start failed"})
		return
	}
	defer tx.Rollback()

	candidateID := uuid.NewString()
	applicationID := uuid.NewString()
	_, err = tx.Exec(`
		INSERT INTO candidates(id, full_name, email, phone, ssn_raw, created_at)
		VALUES ($1,$2,$3,$4,$5,now())
	`, candidateID, req.FullName, strings.ToLower(req.Email), normalizePhone(req.Phone), encSSN)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "candidate create failed", "detail": err.Error()})
		return
	}

	_, err = tx.Exec(`INSERT INTO candidate_identities(id, candidate_id, identity_key, created_at) VALUES ($1,$2,$3,now())`, uuid.NewString(), candidateID, identityKey)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "identity create failed", "detail": err.Error()})
		return
	}

	_, err = tx.Exec(`
		INSERT INTO applications(id, candidate_id, job_id, source_type, stage_code, created_at)
		VALUES ($1,$2,$3,$4,$5,now())
	`, applicationID, candidateID, req.JobID, source, stage)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "application create failed", "detail": err.Error()})
		return
	}

	allTriggers := append(blockTriggers, dupTriggers...)
	_, _ = tx.Exec(`
		INSERT INTO candidate_dedupe_hits(id, candidate_id, risk_score, triggers, created_at)
		VALUES ($1,$2,$3,$4,now())
	`, uuid.NewString(), candidateID, risk, strings.Join(allTriggers, ","))

	_, _ = tx.Exec(`
		INSERT INTO application_pipeline_events(id, application_id, actor_id, to_stage_code, event_type, details)
		VALUES ($1,$2,$3,$4,'CREATE',$5::jsonb)
	`, uuid.NewString(), applicationID, nullableUUID(c.GetString("userID")), stage, `{"source":"`+source+`"}`)

	if err := tx.Commit(); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "commit failed"})
		return
	}

	c.JSON(http.StatusCreated, gin.H{
		"application_id": applicationID,
		"candidate_id":   candidateID,
		"risk_score":     risk,
		"severity":       string(sev),
		"rule_triggers":  allTriggers,
	})
}

