(function () {
  const path = window.location.pathname;
  const RETRY_KEY = "offline:retry_queue";
  const SUPPORT_DRAFT_KEY = "support:draft";
  const TOAST_ID = "global-toast";

  function byId(id) {
    return document.getElementById(id);
  }

  function toast(msg, kind) {
    let el = byId(TOAST_ID);
    if (!el) {
      el = document.createElement("div");
      el.id = TOAST_ID;
      el.style.position = "fixed";
      el.style.bottom = "16px";
      el.style.right = "16px";
      el.style.padding = "10px 12px";
      el.style.borderRadius = "10px";
      el.style.color = "#fff";
      el.style.zIndex = "9999";
      document.body.appendChild(el);
    }
    el.style.background = kind === "error" ? "#be3b32" : kind === "warn" ? "#9a6f00" : "#1f7a45";
    el.textContent = msg;
    setTimeout(() => {
      if (el) el.textContent = "";
    }, 2600);
  }

  function parseJwt(token) {
    try {
      const payload = token.split(".")[1];
      return JSON.parse(atob(payload.replace(/-/g, "+").replace(/_/g, "/")));
    } catch {
      return {};
    }
  }

  function updateSessionLabel() {
    const el = byId("session-user");
    if (!el) return;
    const token = localStorage.getItem("access_token");
    if (!token) {
      el.textContent = "No active session";
      return;
    }
    const claims = parseJwt(token);
    el.textContent = `User: ${claims.username || "unknown"}`;
  }

  function updateNetworkState() {
    const nEl = byId("network-state");
    if (nEl) nEl.textContent = "Network: " + (navigator.onLine ? "online" : "offline");
  }

  function loadQueue() {
    try {
      return JSON.parse(localStorage.getItem(RETRY_KEY) || "[]");
    } catch {
      return [];
    }
  }

  function saveQueue(queue) {
    localStorage.setItem(RETRY_KEY, JSON.stringify(queue));
    const q = byId("queue-state");
    if (q) q.textContent = `Retry queue: ${queue.length}`;
    const sq = byId("support-retry-state");
    if (sq) sq.textContent = `Retry queue: ${queue.length}`;
  }

  function enqueueRetry(item) {
    const q = loadQueue();
    q.push(item);
    saveQueue(q);
  }

  function setVisibility(el, allowed) {
    if (!el) return;
    if (allowed) {
      el.removeAttribute("hidden");
      el.classList.remove("disabled");
      if ("disabled" in el) el.disabled = false;
    } else {
      el.setAttribute("hidden", "hidden");
      el.classList.add("disabled");
      if ("disabled" in el) el.disabled = true;
    }
  }

  function can(perms, module, action) {
    return !!(perms && perms[module] && perms[module][action]);
  }

  async function refreshAccessToken() {
    const refresh = localStorage.getItem("refresh_token");
    if (!refresh) return false;
    const res = await fetch("/rpc/refresh", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: refresh }),
    });
    if (!res.ok) return false;
    const json = await res.json();
    if (json.access_token) {
      localStorage.setItem("access_token", json.access_token);
      return true;
    }
    return false;
  }

  async function apiFetch(url, options) {
    const opts = options || {};
    const method = opts.method || "GET";
    const headers = { "Content-Type": "application/json" };
    if (opts.auth !== false && localStorage.getItem("access_token")) {
      headers.Authorization = "Bearer " + localStorage.getItem("access_token");
    }
    if (opts.idempotency) {
      headers["Idempotency-Key"] = crypto.randomUUID();
    }
    if (opts.stepUp && localStorage.getItem("step_up_token")) {
      headers["X-Step-Up-Token"] = localStorage.getItem("step_up_token");
    }

    const req = {
      method,
      headers,
      body: method === "GET" ? undefined : JSON.stringify(opts.body || {}),
    };

    let res = await fetch(url, req);
    if (res.status === 401 && opts.auth !== false) {
      const refreshed = await refreshAccessToken();
      if (refreshed) {
        req.headers.Authorization = "Bearer " + localStorage.getItem("access_token");
        res = await fetch(url, req);
      }
    }
    const json = await res.json().catch(() => ({}));
    if (!res.ok) {
      throw { status: res.status, ...json };
    }
    return json;
  }

  async function apiGet(url) {
    return apiFetch(url, { method: "GET", auth: true });
  }

  async function apiPost(url, body, opts) {
    return apiFetch(url, { method: "POST", body, auth: true, ...(opts || {}) });
  }

  async function apiPut(url, body, opts) {
    return apiFetch(url, { method: "PUT", body, auth: true, ...(opts || {}) });
  }

  async function flushRetryQueue() {
    if (!navigator.onLine) return;
    const queue = loadQueue();
    if (queue.length === 0) return;
    const remaining = [];
    for (const item of queue) {
      try {
        await apiFetch(item.url, item.options);
      } catch {
        remaining.push(item);
      }
    }
    saveQueue(remaining);
    if (remaining.length === 0) toast("Retry queue flushed", "ok");
  }

  function wireGlobal() {
    updateSessionLabel();
    updateNetworkState();
    saveQueue(loadQueue());

    const logout = byId("logout-btn");
    if (logout) {
      logout.addEventListener("click", () => {
        localStorage.clear();
        window.location.href = "/";
      });
    }

    window.addEventListener("online", async () => {
      updateNetworkState();
      await flushRetryQueue();
    });
    window.addEventListener("offline", updateNetworkState);
    setInterval(flushRetryQueue, 15000);
  }

  async function loadPermissionsAndGate() {
    let me;
    try {
      me = await apiGet("/rpc/api/auth/me");
    } catch {
      return null;
    }
    const perms = me.permissions || {};
    const modules = {
      hiring: can(perms, "hiring", "view") || can(perms, "hiring", "create"),
      support: can(perms, "support", "view") || can(perms, "support", "create"),
      inventory: can(perms, "inventory", "view") || can(perms, "inventory", "create"),
      compliance: can(perms, "compliance", "view") || can(perms, "compliance", "create"),
    };
    setVisibility(byId("nav-hiring"), modules.hiring);
    setVisibility(byId("nav-support"), modules.support);
    setVisibility(byId("nav-inventory"), modules.inventory);
    setVisibility(byId("nav-compliance"), modules.compliance);
    return { me, perms, modules };
  }

  async function loginFlow(e) {
    e.preventDefault();
    const username = byId("username").value.trim();
    const password = byId("password").value;
    const err = byId("login-error");
    err.textContent = "";
    try {
      const res = await apiFetch("/rpc/login", { method: "POST", auth: false, body: { username, password } });
      localStorage.setItem("access_token", res.access_token);
      localStorage.setItem("refresh_token", res.refresh_token);
      window.location.href = "/dashboard";
    } catch (e2) {
      err.textContent = e2.error || "Login failed";
    }
  }

  async function stepUp(actionClass) {
    const pw = window.prompt("Re-enter password for sensitive action");
    if (!pw) return null;
    const res = await apiPost("/rpc/api/auth/step-up", { password: pw, action_class: actionClass });
    localStorage.setItem("step_up_token", res.step_up_token);
    return res.step_up_token;
  }

  function logTo(id, msg) {
    const el = byId(id);
    if (!el) return;
    el.textContent = `[${new Date().toISOString()}] ${msg}\n` + el.textContent;
  }

  function withRetry(url, options) {
    enqueueRetry({ url, options });
  }

  async function initDashboard() {
    const ctx = await loadPermissionsAndGate();
    if (!ctx) return;
    const perms = ctx.perms;
    setVisibility(byId("card-hiring"), ctx.modules.hiring);
    setVisibility(byId("card-support"), ctx.modules.support);
    setVisibility(byId("card-inventory"), ctx.modules.inventory);
    setVisibility(byId("card-compliance"), ctx.modules.compliance);
    setVisibility(byId("create-job-btn"), can(perms, "hiring", "create"));
    setVisibility(byId("create-kiosk-app-btn"), can(perms, "hiring", "create"));
    setVisibility(byId("create-ticket-btn"), can(perms, "support", "create"));
    setVisibility(byId("load-ticket-btn"), can(perms, "support", "view"));
    setVisibility(byId("create-reservation-btn"), can(perms, "inventory", "create"));
    setVisibility(byId("inventory-balance-btn"), can(perms, "inventory", "view"));
    setVisibility(byId("run-crawler-btn"), can(perms, "compliance", "create"));
    setVisibility(byId("retention-status-btn"), can(perms, "compliance", "view"));

    const j = byId("create-job-btn");
    if (j) j.onclick = async () => {
      try {
        const res = await apiPost("/rpc/api/hiring/jobs", { code: `JOB-${Date.now()}`, title: "Warehouse Associate", description: "Inbound ops", site_code: "SITE-A" });
        logTo("activity-log", "Created job: " + res.id);
      } catch (e) { logTo("activity-log", "Create job failed: " + (e.error || e.status)); }
    };
  }

  function validateCsvRows(csv) {
    const lines = csv.split(/\r?\n/).filter((x) => x.trim() !== "");
    const errors = [];
    for (let i = 1; i < lines.length; i++) {
      const cols = lines[i].split(",");
      if (cols.length < 3) errors.push(`row ${i + 1}: expected 3 columns`);
      const email = (cols[1] || "").trim();
      if (email && !email.includes("@")) errors.push(`row ${i + 1}: invalid email`);
    }
    return errors;
  }

  async function initHiring() {
    const ctx = await loadPermissionsAndGate();
    if (!ctx || !ctx.modules.hiring) {
      toast("Not authorized for Hiring module", "error");
      return;
    }

    byId("hiring-job-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        code: byId("job-code").value.trim(),
        title: byId("job-title").value.trim(),
        description: byId("job-description").value.trim(),
        site_code: "SITE-A",
      };
      try {
        const res = await apiPost("/rpc/api/hiring/jobs", payload);
        byId("hiring-job-msg").textContent = `Created job ${res.id}`;
        toast("Job created", "ok");
      } catch (err) {
        byId("hiring-job-msg").textContent = err.error || "Job create failed";
      }
    };

    byId("hiring-manual-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        job_id: byId("manual-job-id").value.trim(),
        full_name: byId("manual-name").value.trim(),
        email: byId("manual-email").value.trim(),
        phone: byId("manual-phone").value.trim(),
        ssn: byId("manual-ssn").value.trim(),
      };
      try {
        const res = await apiPost("/rpc/api/hiring/applications/manual", payload);
        byId("hiring-intake-msg").textContent = `Application ${res.application_id} risk=${res.risk_score} severity=${res.severity}`;
      } catch (err) {
        byId("hiring-intake-msg").textContent = err.error || "Manual intake failed";
      }
    };

    byId("kiosk-submit-btn").onclick = async () => {
      const payload = {
        job_id: byId("manual-job-id").value.trim(),
        full_name: byId("manual-name").value.trim(),
        email: byId("manual-email").value.trim(),
        phone: byId("manual-phone").value.trim(),
        ssn: byId("manual-ssn").value.trim(),
      };
      try {
        const res = await apiPost("/rpc/api/hiring/applications/kiosk", payload);
        byId("hiring-intake-msg").textContent = `Kiosk app ${res.application_id} triggers=${(res.rule_triggers || []).join("|")}`;
      } catch (err) {
        byId("hiring-intake-msg").textContent = err.error || "Kiosk intake failed";
      }
    };

    byId("csv-validate-btn").onclick = () => {
      const csv = byId("csv-text").value;
      const errs = validateCsvRows(csv);
      byId("csv-validation-log").textContent = errs.length ? errs.join("\n") : "CSV validation passed";
    };

    byId("csv-import-btn").onclick = async () => {
      const jobID = byId("csv-job-id").value.trim();
      const csv = byId("csv-text").value;
      const errs = validateCsvRows(csv);
      if (errs.length) {
        byId("csv-validation-log").textContent = errs.join("\n");
        return;
      }
      try {
        const res = await apiPost("/rpc/api/hiring/applications/import-csv", { job_id: jobID, csv });
        byId("csv-validation-log").textContent = `Imported ${res.created} rows`;
      } catch (err) {
        byId("csv-validation-log").textContent = err.error || "CSV import failed";
      }
    };

    byId("pipeline-transition-form").onsubmit = async (e) => {
      e.preventDefault();
      const appID = byId("transition-app-id").value.trim();
      const fromStage = byId("transition-from").value.trim();
      const toStage = byId("transition-to").value.trim();
      let fields = {};
      try {
        fields = JSON.parse(byId("transition-required-json").value || "{}");
      } catch {
        toast("Invalid JSON for required fields", "error");
        return;
      }
      try {
        await apiPost(`/rpc/api/hiring/applications/${appID}/transition`, { from_stage: fromStage, to_stage: toStage, fields });
        logTo("hiring-applications-log", `Transitioned ${appID} ${fromStage}->${toStage}`);
      } catch (err) {
        logTo("hiring-applications-log", `Transition failed: ${err.error || err.status}`);
      }
    };

    byId("load-applications-btn").onclick = async () => {
      try {
        const list = await apiGet("/rpc/api/hiring/applications");
        const lines = (list.applications || []).slice(0, 50).map((a) => `${a.application_id} | ${a.stage_code} | ${a.candidate.full_name} | risk=${a.risk_score}`);
        byId("hiring-applications-log").textContent = lines.join("\n") || "No applications";
      } catch (err) {
        byId("hiring-applications-log").textContent = err.error || "Failed to load applications";
      }
    };
  }

  async function initSupport() {
    const ctx = await loadPermissionsAndGate();
    if (!ctx || !ctx.modules.support) {
      toast("Not authorized for Support module", "error");
      return;
    }

    const ticketForm = byId("support-ticket-form");
    ticketForm.onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        order_id: byId("support-order-id").value.trim(),
        ticket_type: byId("support-ticket-type").value,
        priority: byId("support-priority").value,
        description: byId("support-description").value,
        business_site: "SITE-A",
      };

      const optimisticID = "optimistic-" + Date.now();
      logTo("support-ticket-list-log", `Optimistic ticket ${optimisticID} queued`);
      try {
        const res = await apiPost("/rpc/api/support/tickets", payload);
        localStorage.setItem("last_ticket_id", res.id);
        byId("support-ticket-msg").textContent = `Created ticket ${res.id}; SLA ${res.sla_seconds || ""}`;
        logTo("support-ticket-list-log", `Ticket created ${res.id} due=${res.sla_due_at}`);
      } catch (err) {
        logTo("support-ticket-list-log", `Rollback optimistic ticket ${optimisticID}: ${err.error || err.status}`);
        withRetry("/rpc/api/support/tickets", { method: "POST", body: payload, auth: true });
      }
    };

    byId("support-save-draft").onclick = () => {
      const draft = {
        order_id: byId("support-order-id").value,
        ticket_type: byId("support-ticket-type").value,
        priority: byId("support-priority").value,
        description: byId("support-description").value,
      };
      localStorage.setItem(SUPPORT_DRAFT_KEY, JSON.stringify(draft));
      toast("Support draft saved", "ok");
    };

    byId("support-restore-draft").onclick = () => {
      try {
        const d = JSON.parse(localStorage.getItem(SUPPORT_DRAFT_KEY) || "{}");
        byId("support-order-id").value = d.order_id || "";
        byId("support-ticket-type").value = d.ticket_type || "return_and_refund";
        byId("support-priority").value = d.priority || "STANDARD";
        byId("support-description").value = d.description || "";
        toast("Support draft restored", "ok");
      } catch {
        toast("No valid support draft", "warn");
      }
    };

    byId("support-refresh-list").onclick = async () => {
      try {
        const list = await apiGet("/rpc/api/support/tickets");
        const lines = (list.tickets || []).map((t) => `${t.id} | ${t.status} | prio=${t.priority} | SLA=${t.sla_seconds}s | escalated=${t.escalated}`);
        byId("support-ticket-list-log").textContent = lines.join("\n") || "No tickets";
      } catch (err) {
        byId("support-ticket-list-log").textContent = err.error || "Failed to load tickets";
      }
    };

    byId("support-add-attachment").onclick = async () => {
      const ticketID = localStorage.getItem("last_ticket_id") || window.prompt("Ticket ID");
      if (!ticketID) return;
      const input = byId("support-attach-file");
      const file = input.files && input.files[0];
      if (!file) {
        logTo("support-attach-log", "Select a file first");
        return;
      }
      const allowed = ["image/jpeg", "image/png", "application/pdf"];
      if (!allowed.includes(file.type)) {
        logTo("support-attach-log", `Invalid type ${file.type}`);
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        logTo("support-attach-log", "File exceeds 10MB");
        return;
      }
      const arr = await file.arrayBuffer();
      const hash = await crypto.subtle.digest("SHA-256", arr);
      const checksum = Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
      try {
        await apiPost(`/rpc/api/support/tickets/${ticketID}/attachments`, {
          file_name: file.name,
          mime_type: file.type,
          size_mb: Math.max(1, Math.ceil(file.size / (1024 * 1024))),
          checksum,
        });
        logTo("support-attach-log", `Attachment accepted ${file.name}`);
      } catch (err) {
        logTo("support-attach-log", `Attachment error: ${err.error || err.status}`);
      }
    };

    byId("support-update-form").onsubmit = async (e) => {
      e.preventDefault();
      const ticketID = byId("support-update-ticket-id").value.trim();
      const version = Number(byId("support-update-version").value || "1");
      const description = byId("support-update-description").value;
      try {
        const res = await apiPut(`/rpc/api/support/tickets/${ticketID}`, { description, record_version: version });
        logTo("support-conflict-log", `Updated ticket ${ticketID} version=${res.record_version}`);
      } catch (err) {
        if (err.status === 409) {
          const choice = (window.prompt("Conflict: merge/overwrite/discard", "merge") || "discard").toLowerCase();
          if (choice !== "discard") {
            const r = await apiPost(`/rpc/api/support/tickets/${ticketID}/conflict-resolve`, {
              mode: choice,
              current_version: err.current_version || version,
              expected_version: version,
              description,
            });
            logTo("support-conflict-log", `Conflict resolved: ${JSON.stringify(r)}`);
          } else {
            logTo("support-conflict-log", "Conflict discarded");
          }
        } else {
          logTo("support-conflict-log", `Update failed ${err.error || err.status}`);
        }
      }
    };
  }

  async function initInventory() {
    const ctx = await loadPermissionsAndGate();
    if (!ctx || !ctx.modules.inventory) {
      toast("Not authorized for Inventory module", "error");
      return;
    }

    byId("inventory-op-form").onsubmit = async (e) => {
      e.preventDefault();
      const op = byId("inventory-op-type").value;
      const payload = {
        sku: byId("inventory-sku").value.trim(),
        quantity: Number(byId("inventory-qty").value || "0"),
        from_warehouse: byId("inventory-from-wh").value.trim(),
        to_warehouse: byId("inventory-to-wh").value.trim(),
        reason_code: byId("inventory-reason").value.trim(),
      };
      if (!window.confirm(`Confirm ${op} operation for ${payload.sku}?`)) return;
      try {
        const res = await apiPost(`/rpc/api/inventory/${op}`, payload);
        logTo("inventory-op-log", `Operation success ${JSON.stringify(res)}`);
      } catch (err) {
        logTo("inventory-op-log", `Operation failed ${err.error || err.status}`);
      }
    };

    byId("inventory-cycle-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        warehouse_code: byId("cycle-wh").value.trim(),
        sku: byId("cycle-sku").value.trim(),
        counted_qty: Number(byId("cycle-counted").value || "0"),
        reason_code: byId("cycle-reason").value.trim(),
      };
      if (!window.confirm("Confirm cycle count submission?")) return;
      try {
        const res = await apiPost("/rpc/api/inventory/cycle-counts", payload);
        logTo("inventory-cycle-log", `Cycle session ${res.session_id}, approval=${res.requires_approval}`);
      } catch (err) {
        logTo("inventory-cycle-log", `Cycle count failed ${err.error || err.status}`);
      }
    };

    byId("inventory-refresh-balances").onclick = async () => {
      try {
        const json = await apiGet("/rpc/api/inventory/balances?site=SITE-A");
        const lines = (json.balances || []).map((b) => `${b.warehouse}/${b.sub_warehouse} ${b.sku} on_hand=${b.on_hand} reserved=${b.reserved} low=${b.low_stock_alert}`);
        byId("inventory-balances-log").textContent = lines.join("\n") || "No balances";
      } catch (err) {
        byId("inventory-balances-log").textContent = err.error || "Load balances failed";
      }
    };

    byId("inventory-create-reservation").onclick = async () => {
      const payload = { order_id: `ORD-${Date.now()}`, sku: "SKU-100", quantity: 2, site_code: "SITE-A" };
      if (!window.confirm("Create reservation?")) return;
      try {
        const res = await apiPost("/rpc/api/inventory/reservations/order-create", payload, { idempotency: true });
        logTo("inventory-reservations-log", `Reservation ${res.id} status=${res.status} wh=${res.warehouse}`);
      } catch (err) {
        logTo("inventory-reservations-log", `Reservation failed ${err.error || err.status}`);
      }
    };

    byId("inventory-refresh-reservations").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/inventory/reservations");
