      } catch (err) {
        logTo("activity-log", err.error || "job failed");
      }
    };

    const t = byId("create-ticket-btn");
    if (t) t.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/support/tickets", { order_id: "ORD-1001", ticket_type: "return_and_refund", priority: "HIGH", description: "Quick ticket", business_site: "SITE-A" });
        localStorage.setItem("last_ticket_id", r.id);
        logTo("activity-log", `Created ticket ${r.id}`);
      } catch (err) {
