		WHERE id=$1
	`, req.TicketID)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "refund approval failed", "detail": err.Error()})
		return
	}

	_, _ = h.DB.Exec(`
		INSERT INTO audit_logs(actor_id, action_class, entity_type, entity_id, event_data)
