        logTo("compliance-crawler-log", err.error || "status failed");
      }
    };
    byId("compliance-retention-status").onclick = async () => {
      try {
        const r = await apiGet("/rpc/api/compliance/retention/jobs");
        byId("compliance-retention-log").textContent = JSON.stringify(r, null, 2);
      } catch (err) {
        byId("compliance-retention-log").textContent = err.error || "retention failed";
      }
    };

    byId("compliance-delete-create").onclick = async () => {
      const ref = byId("compliance-subject-ref").value.trim();
      try {
        const r = await apiPost("/rpc/api/compliance/deletion-requests", { subject_ref: ref });
        byId("compliance-process-id").value = r.id;
        logTo("compliance-delete-log", `Created ${r.id}`);
      } catch (err) {
        logTo("compliance-delete-log", err.error || "create failed");
      }
    };
    byId("compliance-list-delete").onclick = async () => {
      try {
        const r = await apiGet("/rpc/api/compliance/deletion-requests");
        const lines = (r.requests || []).map((x) => `${x.id} | ${x.subject_ref} | ${x.status} | due=${x.due_at}`);
        byId("compliance-delete-log").textContent = lines.join("\n") || "No requests";
      } catch (err) {
        byId("compliance-delete-log").textContent = err.error || "list failed";
      }
    };
    byId("compliance-delete-process").onclick = async () => {
      const id = byId("compliance-process-id").value.trim();
      try {
        const r = await apiPost(`/rpc/api/compliance/deletion-requests/${id}/process`, {});
        logTo("compliance-delete-log", `Processed ${id} policy=${r.policy}`);
      } catch (err) {
        logTo("compliance-delete-log", err.error || "process failed");
      }
    };

    byId("compliance-audit-load").onclick = async () => {
      const action = encodeURIComponent(byId("compliance-audit-filter").value.trim());
      const page = encodeURIComponent(byId("compliance-audit-page").value.trim() || "1");
      const limit = encodeURIComponent(byId("compliance-audit-limit").value.trim() || "50");
      try {
        const r = await apiGet(`/rpc/api/compliance/audit-logs?page=${page}&limit=${limit}&action=${action}`);
        const lines = (r.logs || []).map((l) => `${l.at} | ${l.actor} | ${l.action}`);
        byId("compliance-audit-log").textContent = lines.join("\n") || "No logs";
      } catch (err) {
        byId("compliance-audit-log").textContent = err.error || "audit failed";
      }
    };

    byId("compliance-audit-export").onclick = async () => {
      try {
        await stepUp("export");
        const text = await apiFetch("/rpc/api/compliance/audit-logs/export?format=csv&limit=500", { method: "GET", auth: true, stepUp: true });
        byId("compliance-audit-log").textContent = String(text).slice(0, 3000);
      } catch (err) {
        toast(err.error || "Export failed", "error");
      }
    };
  }

  function wireQuickButtons() {
    const j = byId("create-job-btn");
    if (j) j.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/hiring/jobs", { code: `JOB-${Date.now()}`, title: "Warehouse Associate", description: "Inbound ops", site_code: "SITE-A" });
        logTo("activity-log", `Created job ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "job failed");
      }
    };

    const t = byId("create-ticket-btn");
    if (t) t.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/support/tickets", { order_id: "ORD-1001", ticket_type: "return_and_refund", priority: "HIGH", description: "Quick ticket", business_site: "SITE-A" });
        localStorage.setItem("last_ticket_id", r.id);
        logTo("activity-log", `Created ticket ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "ticket failed");
      }
    };

    const rb = byId("create-reservation-btn");
    if (rb) rb.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/inventory/reservations/order-create", { order_id: `ORD-${Date.now()}`, sku: "SKU-100", quantity: 2, site_code: "SITE-A" }, { idempotency: true });
        logTo("activity-log", `Reservation ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "reservation failed");
      }
    };
  }

  async function initRoute() {
    wireGlobal();
    if (path === "/") {
      const form = byId("login-form");
      if (form) form.addEventListener("submit", loginFlow);
      return;
    }

    const ctx = await fetchUserContext();
    if (!ctx) {
      toast("Session missing or expired, login again", "warn");
      return;
    }

    if (path === "/dashboard") {
      await initDashboard(ctx);
      wireQuickButtons();
      return;
    }
    if (path === "/hiring") return initHiring(ctx);
    if (path === "/hiring/kiosk") return initKiosk();
    if (path === "/support") return initSupport(ctx);
    if (path === "/inventory") return initInventory(ctx);
    if (path === "/compliance") return initCompliance(ctx);
  }

  initRoute();
})();

