(function () {
  const path = window.location.pathname;
  const RETRY_KEY_BASE = "offline:retry_queue";
  const SUPPORT_DRAFT_KEY_BASE = "support:draft";
  const LAST_TICKET_KEY_BASE = "support:last_ticket_id";
  const AUTH_KEYS = {
    access: "auth:access_token",
    refresh: "auth:refresh_token",
    stepUp: "auth:step_up_token",
    userID: "auth:user_id",
  };

  const session = {
    get(key) {
      try {
        return window.sessionStorage.getItem(key) || "";
      } catch {
        return "";
      }
    },
    set(key, val) {
      try {
        if (typeof val === "string" && val !== "") window.sessionStorage.setItem(key, val);
      } catch {}
    },
    remove(key) {
      try {
        window.sessionStorage.removeItem(key);
      } catch {}
    },
    clear() {
      try {
        window.sessionStorage.clear();
      } catch {}
    },
    accessToken() {
      return session.get(AUTH_KEYS.access);
    },
    refreshToken() {
      return session.get(AUTH_KEYS.refresh);
    },
    stepUpToken() {
      return session.get(AUTH_KEYS.stepUp);
    },
    userID() {
      return session.get(AUTH_KEYS.userID);
    },
    setAuth(access, refresh, userID) {
      session.set(AUTH_KEYS.access, access || "");
      session.set(AUTH_KEYS.refresh, refresh || "");
      session.set(AUTH_KEYS.userID, userID || "");
    },
    clearAuth() {
      session.remove(AUTH_KEYS.access);
      session.remove(AUTH_KEYS.refresh);
      session.remove(AUTH_KEYS.stepUp);
      session.remove(AUTH_KEYS.userID);
    },
  };

  function scopedKey(base, explicitUserID) {
    const uid = (explicitUserID || session.userID() || "anon").trim() || "anon";
    return `${base}:${uid}`;
  }

  function clearUserScopedCache(userID) {
    if (!userID) return;
    localStorage.removeItem(scopedKey(RETRY_KEY_BASE, userID));
    localStorage.removeItem(scopedKey(SUPPORT_DRAFT_KEY_BASE, userID));
    localStorage.removeItem(scopedKey(LAST_TICKET_KEY_BASE, userID));
  }

  function byId(id) {
    return document.getElementById(id);
  }

  function toast(msg, kind) {
    let el = byId("global-toast");
    if (!el) {
      el = document.createElement("div");
      el.id = "global-toast";
      el.className = "toast";
      document.body.appendChild(el);
    }
    el.className = `toast ${kind || "info"}`;
    el.textContent = msg;
    setTimeout(() => {
      if (el) el.textContent = "";
    }, 2600);
  }

  function setStatusBadge(id, text, kind) {
    const el = byId(id);
    if (!el) return;
    el.textContent = text;
    el.className = `status-badge ${kind || "info"}`;
  }

  function setVisibility(el, allowed, messageIfDenied) {
    if (!el) return;
    if (allowed) {
      el.removeAttribute("hidden");
      el.classList.remove("disabled");
      if ("disabled" in el) el.disabled = false;
      if (messageIfDenied && el.dataset.deniedMessage) el.dataset.deniedMessage = "";
    } else {
      el.setAttribute("hidden", "hidden");
      el.classList.add("disabled");
      if ("disabled" in el) el.disabled = true;
      if (messageIfDenied) el.dataset.deniedMessage = messageIfDenied;
    }
  }

  function can(perms, module, action) {
    return !!(perms && perms[module] && perms[module][action]);
  }

  function parseJwt(token) {
    try {
      const payload = token.split(".")[1];
      return JSON.parse(atob(payload.replace(/-/g, "+").replace(/_/g, "/")));
    } catch {
      return {};
    }
  }

  function updateSessionLabel() {
    const el = byId("session-user");
    if (!el) return;
    const token = session.accessToken();
    if (!token) {
      el.textContent = "No active session";
      return;
    }
    const claims = parseJwt(token);
    el.textContent = `User: ${claims.username || "unknown"}`;
  }

  function updateNetworkState() {
    const el = byId("network-state");
    if (el) el.textContent = `Network: ${navigator.onLine ? "online" : "offline"}`;
  }

  function loadQueue() {
    try {
      return JSON.parse(localStorage.getItem(scopedKey(RETRY_KEY_BASE)) || "[]");
    } catch {
      return [];
    }
  }

  function saveQueue(queue) {
    localStorage.setItem(scopedKey(RETRY_KEY_BASE), JSON.stringify(queue));
    const q1 = byId("queue-state");
    const q2 = byId("support-retry-state");
    if (q1) q1.textContent = `Retry queue: ${queue.length}`;
    if (q2) q2.textContent = `Retry queue: ${queue.length}`;
  }

  function enqueueRetry(url, options) {
    const q = loadQueue();
    q.push({ url, options });
    saveQueue(q);
  }

  async function refreshAccessToken() {
    const refresh = session.refreshToken();
    if (!refresh) return false;
    const res = await fetch("/rpc/refresh", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: refresh }),
    });
    if (!res.ok) return false;
    const json = await res.json().catch(() => ({}));
    if (!json.access_token) return false;
    session.set(AUTH_KEYS.access, json.access_token);
    return true;
  }

  async function apiFetch(url, opts) {
    const options = opts || {};
    const method = options.method || "GET";
    const headers = { "Content-Type": "application/json" };
    if (options.auth !== false && session.accessToken()) {
      headers.Authorization = `Bearer ${session.accessToken()}`;
    }
    if (options.idempotency) headers["Idempotency-Key"] = crypto.randomUUID();
    if (options.stepUp && session.stepUpToken()) {
      headers["X-Step-Up-Token"] = session.stepUpToken();
    }

    const req = {
      method,
      headers,
      body: method === "GET" ? undefined : JSON.stringify(options.body || {}),
    };

    let res = await fetch(url, req);
    if (res.status === 401 && options.auth !== false) {
      if (await refreshAccessToken()) {
        req.headers.Authorization = `Bearer ${session.accessToken()}`;
        res = await fetch(url, req);
      }
    }

    const contentType = res.headers.get("Content-Type") || "";
    const body = contentType.includes("application/json")
      ? await res.json().catch(() => ({}))
      : await res.text().catch(() => "");

    if (options.stepUp && res.ok) {
      session.remove(AUTH_KEYS.stepUp);
    }
    if (!res.ok) throw { status: res.status, ...(typeof body === "object" ? body : { error: body }) };
    return body;
  }

  const apiGet = (url) => apiFetch(url, { method: "GET", auth: true });
  const apiPost = (url, body, extra) => apiFetch(url, { method: "POST", body, auth: true, ...(extra || {}) });
  const apiPut = (url, body) => apiFetch(url, { method: "PUT", body, auth: true });

  async function flushRetryQueue() {
    if (!navigator.onLine) return;
    const queue = loadQueue();
    if (!queue.length) return;
    const remaining = [];
    for (const item of queue) {
      try {
        await apiFetch(item.url, item.options || {});
      } catch {
        remaining.push(item);
      }
    }
    saveQueue(remaining);
    if (!remaining.length) toast("Retry queue flushed", "ok");
  }

  async function fetchUserContext() {
    try {
      return await apiGet("/rpc/api/auth/me");
    } catch {
      return null;
    }
  }

  function applyModuleVisibility(ctx) {
    const perms = (ctx && ctx.permissions) || {};
    const moduleVisible = {
      hiring: can(perms, "hiring", "view") || can(perms, "hiring", "create"),
      support: can(perms, "support", "view") || can(perms, "support", "create"),
      inventory: can(perms, "inventory", "view") || can(perms, "inventory", "create"),
      compliance: can(perms, "compliance", "view") || can(perms, "compliance", "create"),
    };
    setVisibility(byId("nav-hiring"), moduleVisible.hiring);
    setVisibility(byId("nav-support"), moduleVisible.support);
    setVisibility(byId("nav-inventory"), moduleVisible.inventory);
    setVisibility(byId("nav-compliance"), moduleVisible.compliance);
    return { perms, moduleVisible };
  }

  function applyActionGates(perms, mapping) {
    mapping.forEach((m) => {
      const el = byId(m.id);
      const allowed = can(perms, m.module, m.action);
      setVisibility(el, allowed, `${m.module}:${m.action} required`);
    });
  }

  function logTo(id, msg) {
    const el = byId(id);
    if (!el) return;
    el.textContent = `[${new Date().toISOString()}] ${msg}\n` + el.textContent;
  }

  async function loginFlow(e) {
    e.preventDefault();
    const username = byId("username").value.trim();
    const password = byId("password").value;
    const err = byId("login-error");
    err.textContent = "";
    try {
      const res = await apiFetch("/rpc/login", { method: "POST", auth: false, body: { username, password } });
      const claims = parseJwt(res.access_token || "");
      const oldUser = session.userID();
      const newUser = claims.sub || "";
      if (oldUser && newUser && oldUser !== newUser) clearUserScopedCache(oldUser);
      session.setAuth(res.access_token, res.refresh_token, newUser);
      window.location.href = "/dashboard";
    } catch (ex) {
      err.textContent = ex.error || "Login failed";
    }
  }

  async function stepUp(actionClass) {
    const pw = window.prompt("Re-enter password for sensitive action");
    if (!pw) return null;
    const res = await apiPost("/rpc/api/auth/step-up", { password: pw, action_class: actionClass });
    session.set(AUTH_KEYS.stepUp, res.step_up_token || "");
    return res.step_up_token;
  }

  function wireGlobal() {
    updateSessionLabel();
    updateNetworkState();
    saveQueue(loadQueue());

    const logout = byId("logout-btn");
    if (logout) {
      logout.addEventListener("click", () => {
        clearUserScopedCache(session.userID());
        session.clearAuth();
        window.location.href = "/";
      });
    }

    window.addEventListener("online", async () => {
      updateNetworkState();
      await flushRetryQueue();
    });
    window.addEventListener("offline", updateNetworkState);
    setInterval(flushRetryQueue, 15000);
  }

  async function initDashboard(ctx) {
    const { perms, moduleVisible } = applyModuleVisibility(ctx);
    setVisibility(byId("card-hiring"), moduleVisible.hiring);
    setVisibility(byId("card-support"), moduleVisible.support);
    setVisibility(byId("card-inventory"), moduleVisible.inventory);
    setVisibility(byId("card-compliance"), moduleVisible.compliance);

    applyActionGates(perms, [
      { id: "create-job-btn", module: "hiring", action: "create" },
      { id: "create-kiosk-app-btn", module: "hiring", action: "create" },
      { id: "create-ticket-btn", module: "support", action: "create" },
      { id: "load-ticket-btn", module: "support", action: "view" },
      { id: "create-reservation-btn", module: "inventory", action: "create" },
      { id: "inventory-balance-btn", module: "inventory", action: "view" },
      { id: "run-crawler-btn", module: "compliance", action: "create" },
      { id: "retention-status-btn", module: "compliance", action: "view" },
    ]);
  }

  function validateCsv(csv) {
    const rows = csv.split(/\r?\n/).filter((r) => r.trim() !== "");
    const errors = [];
    for (let i = 1; i < rows.length; i++) {
      const cols = rows[i].split(",");
      if (cols.length < 3) errors.push(`row ${i + 1}: expected 3 cols`);
      if (cols[1] && !cols[1].includes("@")) errors.push(`row ${i + 1}: bad email`);
    }
    return errors;
  }

  async function initHiring(ctx) {
    const { perms, moduleVisible } = applyModuleVisibility(ctx);
    if (!moduleVisible.hiring) {
      toast("Not authorized for Hiring module", "error");
      return;
    }

    applyActionGates(perms, [
      { id: "hiring-create-job", module: "hiring", action: "create" },
      { id: "hiring-manual-submit", module: "hiring", action: "create" },
      { id: "kiosk-submit-btn", module: "hiring", action: "create" },
      { id: "csv-import-btn", module: "hiring", action: "create" },
      { id: "pipeline-save-btn", module: "hiring", action: "update" },
      { id: "pipeline-validate-btn", module: "hiring", action: "update" },
      { id: "pipeline-transition-btn", module: "hiring", action: "update" },
      { id: "load-applications-btn", module: "hiring", action: "view" },
      { id: "load-timeline-btn", module: "hiring", action: "view" },
    ]);

    const kioskURL = `${window.location.origin}/hiring/kiosk`;
    const qr = byId("hiring-kiosk-qr");
    if (qr) qr.src = `/hiring/kiosk/qr?url=${encodeURIComponent(kioskURL)}`;
    const kioskLink = byId("hiring-kiosk-url");
    if (kioskLink) kioskLink.href = kioskURL;

    byId("hiring-create-job").onclick = async () => {
      const payload = {
        code: byId("job-code").value.trim(),
        title: byId("job-title").value.trim(),
        description: byId("job-description").value.trim(),
        site_code: "SITE-A",
      };
      try {
        const res = await apiPost("/rpc/api/hiring/jobs", payload);
        byId("hiring-job-msg").textContent = `Created job ${res.id}`;
      } catch (err) {
        byId("hiring-job-msg").textContent = err.error || "Create failed";
      }
    };

    byId("hiring-load-jobs").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/hiring/jobs");
        const lines = (res.jobs || []).map((j) => `${j.id} | ${j.code} | ${j.title}`);
        byId("hiring-jobs-log").textContent = lines.join("\n") || "No jobs";
      } catch (err) {
        byId("hiring-jobs-log").textContent = err.error || "Load jobs failed";
      }
    };

    async function submitIntake(endpoint) {
      const payload = {
        job_id: byId("manual-job-id").value.trim(),
        full_name: byId("manual-name").value.trim(),
        email: byId("manual-email").value.trim(),
        phone: byId("manual-phone").value.trim(),
        ssn: byId("manual-ssn").value.trim(),
      };
      try {
        const res = await apiPost(endpoint, payload);
        byId("hiring-intake-msg").textContent = `Application ${res.application_id}, risk=${res.risk_score}`;
        const severity = (res.severity || "info").toLowerCase();
        setStatusBadge("hiring-rule-status", `Rule outcome: ${severity}; triggers=${(res.rule_triggers || []).join(",")}`, severity === "block" ? "error" : severity === "warn" ? "warn" : "info");
      } catch (err) {
        byId("hiring-intake-msg").textContent = err.error || "Intake failed";
        setStatusBadge("hiring-rule-status", `Rule failure: ${err.error || err.status}`, "error");
      }
    }
    byId("hiring-manual-submit").onclick = () => submitIntake("/rpc/api/hiring/applications/manual");
    byId("kiosk-submit-btn").onclick = () => submitIntake("/rpc/api/hiring/applications/kiosk");

    byId("csv-validate-btn").onclick = () => {
      const errs = validateCsv(byId("csv-text").value);
      byId("csv-validation-log").textContent = errs.length ? errs.join("\n") : "CSV validation passed";
    };
    byId("csv-import-btn").onclick = async () => {
      const csv = byId("csv-text").value;
      const errs = validateCsv(csv);
      if (errs.length) {
        byId("csv-validation-log").textContent = errs.join("\n");
        return;
      }
      try {
        const res = await apiPost("/rpc/api/hiring/applications/import-csv", { job_id: byId("csv-job-id").value.trim(), csv });
        byId("csv-validation-log").textContent = `Imported ${res.created} rows`;
      } catch (err) {
        byId("csv-validation-log").textContent = err.error || "CSV import failed";
      }
    };

    byId("pipeline-validate-btn").onclick = async () => {
      try {
        const stages = JSON.parse(byId("pipeline-stages-json").value || "[]");
        const transitions = JSON.parse(byId("pipeline-transitions-json").value || "[]");
        await apiPost("/rpc/api/hiring/pipelines/validate", { code: byId("pipeline-code").value.trim(), name: byId("pipeline-name").value.trim(), stages, transitions });
        logTo("pipeline-config-log", "Pipeline definition valid");
      } catch (err) {
        logTo("pipeline-config-log", `Validation failed: ${err.error || err.status}`);
      }
    };

    byId("pipeline-save-btn").onclick = async () => {
      try {
        const stages = JSON.parse(byId("pipeline-stages-json").value || "[]");
        const transitions = JSON.parse(byId("pipeline-transitions-json").value || "[]");
        const res = await apiPost("/rpc/api/hiring/pipelines/templates", { code: byId("pipeline-code").value.trim(), name: byId("pipeline-name").value.trim(), stages, transitions });
        logTo("pipeline-config-log", `Saved template ${res.id}`);
      } catch (err) {
        logTo("pipeline-config-log", `Save failed: ${err.error || err.status}`);
      }
    };

    byId("pipeline-load-btn").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/hiring/pipelines/templates");
        const lines = (res.templates || []).map((t) => `${t.id} | ${t.code} | ${t.name} | active=${t.active}`);
        logTo("pipeline-config-log", lines.join("\n") || "No templates");
      } catch (err) {
        logTo("pipeline-config-log", `Load templates failed: ${err.error || err.status}`);
      }
    };

    byId("load-allowed-transitions-btn").onclick = async () => {
      const appID = byId("transition-app-id").value.trim();
      if (!appID) return;
      try {
        const res = await apiGet(`/rpc/api/hiring/applications/${appID}/allowed-transitions`);
        const lines = (res.allowed_transitions || []).map((t) => `${res.current_stage} -> ${t.to_stage} | req=${t.required_fields || "-"} | rule=${t.screening_rule || "-"}`);
        byId("allowed-transitions-log").textContent = lines.join("\n") || "No transitions";
      } catch (err) {
        byId("allowed-transitions-log").textContent = err.error || "Failed to load allowed transitions";
      }
    };

    byId("pipeline-transition-btn").onclick = async () => {
      const appID = byId("transition-app-id").value.trim();
      let fields;
      try {
        fields = JSON.parse(byId("transition-required-json").value || "{}");
      } catch {
        toast("Required fields JSON is invalid", "error");
        return;
      }
      try {
        await apiPost(`/rpc/api/hiring/applications/${appID}/transition`, {
          from_stage: byId("transition-from").value.trim(),
          to_stage: byId("transition-to").value.trim(),
          fields,
        });
        logTo("hiring-applications-log", `Transitioned application ${appID}`);
      } catch (err) {
        logTo("hiring-applications-log", `Transition failed: ${err.error || err.status}`);
      }
    };

    byId("load-applications-btn").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/hiring/applications");
        const lines = (res.applications || []).map((a) => `${a.application_id} | stage=${a.stage_code} | ${a.candidate.full_name} | risk=${a.risk_score}`);
        byId("hiring-applications-log").textContent = lines.join("\n") || "No applications";
      } catch (err) {
        byId("hiring-applications-log").textContent = err.error || "Failed to load applications";
      }
    };

    byId("load-timeline-btn").onclick = async () => {
      const appID = byId("timeline-app-id").value.trim();
      if (!appID) return;
      try {
        const res = await apiGet(`/rpc/api/hiring/applications/${appID}/events`);
        const lines = (res.events || []).map((e) => `${e.at} | ${e.event_type} | ${e.from || "-"} -> ${e.to || "-"}\n${e.details}`);
        byId("hiring-timeline-log").textContent = lines.join("\n\n") || "No events";
      } catch (err) {
        byId("hiring-timeline-log").textContent = err.error || "Failed to load timeline";
      }
    };
  }

  async function initKiosk() {
    const submit = byId("kiosk-page-submit");
    if (!submit) return;
    submit.onclick = async () => {
      const payload = {
        job_id: byId("kiosk-job-id").value.trim(),
        full_name: byId("kiosk-name").value.trim(),
        email: byId("kiosk-email").value.trim(),
        phone: byId("kiosk-phone").value.trim(),
        ssn: byId("kiosk-ssn").value.trim(),
      };
      const msg = byId("kiosk-page-msg");
      try {
        const res = await apiPost("/rpc/api/hiring/applications/kiosk", payload);
        msg.textContent = `Application captured: ${res.application_id}`;
        toast("Kiosk submission saved", "ok");
      } catch (err) {
        msg.textContent = err.error || "Kiosk submission failed";
      }
    };
  }

  async function initSupport(ctx) {
    const { perms, moduleVisible } = applyModuleVisibility(ctx);
    if (!moduleVisible.support) {
      toast("Not authorized for Support module", "error");
      return;
    }
    applyActionGates(perms, [
      { id: "support-create-ticket", module: "support", action: "create" },
      { id: "support-add-attachment", module: "support", action: "update" },
      { id: "support-refresh-list", module: "support", action: "view" },
      { id: "support-update-submit", module: "support", action: "update" },
    ]);

    byId("support-create-ticket").onclick = async () => {
      const payload = {
        order_id: byId("support-order-id").value.trim(),
        ticket_type: byId("support-ticket-type").value,
        priority: byId("support-priority").value,
        description: byId("support-description").value,
        business_site: "SITE-A",
      };
      const optimisticID = "optimistic-" + Date.now();
      logTo("support-ticket-list-log", `Optimistic ${optimisticID} created`);
      try {
        const res = await apiPost("/rpc/api/support/tickets", payload);
        localStorage.setItem(scopedKey(LAST_TICKET_KEY_BASE), res.id);
        byId("support-ticket-msg").textContent = `Created ticket ${res.id}; SLA due ${res.sla_due_at}; escalated=${res.eligibility ? "no" : "unknown"}`;
      } catch (err) {
        logTo("support-ticket-list-log", `Rollback ${optimisticID}: ${err.error || err.status}`);
        enqueueRetry("/rpc/api/support/tickets", { method: "POST", body: payload, auth: true });
      }
    };

    byId("support-save-draft").onclick = () => {
      localStorage.setItem(scopedKey(SUPPORT_DRAFT_KEY_BASE), JSON.stringify({
        order_id: byId("support-order-id").value,
        ticket_type: byId("support-ticket-type").value,
        priority: byId("support-priority").value,
        description: byId("support-description").value,
      }));
      setStatusBadge("support-draft-status", "Draft saved", "info");
      toast("Draft saved", "ok");
    };

    byId("support-restore-draft").onclick = () => {
      try {
        const d = JSON.parse(localStorage.getItem(scopedKey(SUPPORT_DRAFT_KEY_BASE)) || "{}");
        byId("support-order-id").value = d.order_id || "";
        byId("support-ticket-type").value = d.ticket_type || "return_and_refund";
        byId("support-priority").value = d.priority || "STANDARD";
        byId("support-description").value = d.description || "";
        setStatusBadge("support-draft-status", "Draft restored", "ok");
      } catch {
        setStatusBadge("support-draft-status", "No valid draft", "warn");
      }
    };

    byId("support-refresh-list").onclick = async () => {
      try {
        const list = await apiGet("/rpc/api/support/tickets");
        const lines = (list.tickets || []).map((t) => `${t.id} | ${t.status} | SLA=${t.sla_seconds}s | escalated=${t.escalated}`);
        byId("support-ticket-list-log").textContent = lines.join("\n") || "No tickets";
      } catch (err) {
        byId("support-ticket-list-log").textContent = err.error || "Failed to load tickets";
      }
    };

    byId("support-add-attachment").onclick = async () => {
      const ticketID = localStorage.getItem(scopedKey(LAST_TICKET_KEY_BASE)) || prompt("Ticket ID");
      if (!ticketID) return;
      const input = byId("support-attach-file");
      const file = input.files && input.files[0];
      if (!file) return logTo("support-attach-log", "Select a file first");
      const allowed = ["image/jpeg", "image/png", "application/pdf"];
      if (!allowed.includes(file.type)) return logTo("support-attach-log", "Only JPG/PNG/PDF accepted");
      if (file.size > 10 * 1024 * 1024) return logTo("support-attach-log", "File exceeds 10MB");
      const hash = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
      const checksum = Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
      try {
        await apiPost(`/rpc/api/support/tickets/${ticketID}/attachments`, {
          file_name: file.name,
          mime_type: file.type,
          size_mb: Math.max(1, Math.ceil(file.size / (1024 * 1024))),
          checksum,
        });
        logTo("support-attach-log", `Attachment accepted ${file.name}`);
      } catch (err) {
        logTo("support-attach-log", `Attachment failed ${err.error || err.status}`);
      }
    };

    byId("support-update-submit").onclick = async () => {
      const ticketID = byId("support-update-ticket-id").value.trim();
      const version = Number(byId("support-update-version").value || "1");
      const description = byId("support-update-description").value;
      try {
        const res = await apiPut(`/rpc/api/support/tickets/${ticketID}`, { description, record_version: version });
        logTo("support-conflict-log", `Update succeeded version=${res.record_version}`);
      } catch (err) {
        if (err.status !== 409) {
          logTo("support-conflict-log", `Update failed: ${err.error || err.status}`);
          return;
        }
        const choice = (prompt("Version conflict. Choose merge, overwrite, or discard.", "merge") || "discard").toLowerCase();
        if (choice === "discard") {
          logTo("support-conflict-log", "Conflict discarded. Latest server version kept.");
          return;
        }
        try {
          const r = await apiPost(`/rpc/api/support/tickets/${ticketID}/conflict-resolve`, {
            mode: choice,
            current_version: err.current_version || version,
            expected_version: version,
            description,
          });
          logTo("support-conflict-log", `Conflict resolved (${choice}): ${JSON.stringify(r)}`);
        } catch (e2) {
          logTo("support-conflict-log", `Conflict resolution failed: ${e2.error || e2.status}`);
        }
      }
    };
  }

  async function initInventory(ctx) {
    const { perms, moduleVisible } = applyModuleVisibility(ctx);
    if (!moduleVisible.inventory) return toast("Not authorized for Inventory", "error");
    applyActionGates(perms, [
      { id: "inventory-op-submit", module: "inventory", action: "create" },
      { id: "inventory-cycle-submit", module: "inventory", action: "create" },
      { id: "inventory-refresh-balances", module: "inventory", action: "view" },
      { id: "inventory-create-reservation", module: "inventory", action: "create" },
      { id: "inventory-refresh-reservations", module: "inventory", action: "view" },
    ]);

    byId("inventory-op-submit").onclick = async () => {
      const op = byId("inventory-op-type").value;
      const payload = {
        sku: byId("inventory-sku").value.trim(),
        quantity: Number(byId("inventory-qty").value || "0"),
        from_warehouse: byId("inventory-from-wh").value.trim(),
        to_warehouse: byId("inventory-to-wh").value.trim(),
        reason_code: byId("inventory-reason").value.trim(),
      };
      if (!confirm(`Confirm ${op} for ${payload.sku}?`)) return;
      try {
        const res = await apiPost(`/rpc/api/inventory/${op}`, payload);
        logTo("inventory-op-log", JSON.stringify(res));
      } catch (err) {
        logTo("inventory-op-log", err.error || `failed ${err.status}`);
      }
    };

    byId("inventory-cycle-submit").onclick = async () => {
      const payload = {
        warehouse_code: byId("cycle-wh").value.trim(),
        sku: byId("cycle-sku").value.trim(),
        counted_qty: Number(byId("cycle-counted").value || "0"),
        reason_code: byId("cycle-reason").value.trim(),
      };
      if (!confirm("Confirm cycle count?")) return;
      try {
        const res = await apiPost("/rpc/api/inventory/cycle-counts", payload);
        logTo("inventory-cycle-log", `session=${res.session_id} requires_approval=${res.requires_approval}`);
      } catch (err) {
        logTo("inventory-cycle-log", err.error || "cycle failed");
      }
    };

    byId("inventory-refresh-balances").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/inventory/balances?site=SITE-A");
        const lines = (res.balances || []).map((b) => `${b.warehouse}/${b.sub_warehouse} ${b.sku} on_hand=${b.on_hand} reserved=${b.reserved} low_stock=${b.low_stock_alert}`);
        byId("inventory-balances-log").textContent = lines.join("\n") || "No balances";
      } catch (err) {
        byId("inventory-balances-log").textContent = err.error || "Load balances failed";
      }
    };

    byId("inventory-create-reservation").onclick = async () => {
      const payload = { order_id: `ORD-${Date.now()}`, sku: "SKU-100", quantity: 2, site_code: "SITE-A" };
      if (!confirm("Create reservation?")) return;
      try {
        const res = await apiPost("/rpc/api/inventory/reservations/order-create", payload, { idempotency: true });
        logTo("inventory-reservations-log", `${res.id} ${res.status} ${res.warehouse}`);
      } catch (err) {
        logTo("inventory-reservations-log", err.error || "reservation failed");
      }
    };

    byId("inventory-refresh-reservations").onclick = async () => {
      try {
        const res = await apiGet("/rpc/api/inventory/reservations");
        const lines = (res.reservations || []).map((r) => `${r.id} | ${r.status} | ${r.warehouse_code} | ${r.sku} | hold=${r.hold_expires_at}`);
        byId("inventory-reservations-log").textContent = lines.join("\n") || "No reservations";
      } catch (err) {
        byId("inventory-reservations-log").textContent = err.error || "Load reservations failed";
      }
    };
  }

  async function initCompliance(ctx) {
    const { perms, moduleVisible } = applyModuleVisibility(ctx);
    if (!moduleVisible.compliance) return toast("Not authorized for Compliance", "error");

    applyActionGates(perms, [
      { id: "compliance-crawler-run", module: "compliance", action: "create" },
      { id: "compliance-crawler-status", module: "compliance", action: "view" },
      { id: "compliance-retention-status", module: "compliance", action: "view" },
      { id: "compliance-delete-create", module: "compliance", action: "create" },
      { id: "compliance-list-delete", module: "compliance", action: "view" },
      { id: "compliance-delete-process", module: "compliance", action: "approve" },
      { id: "compliance-audit-load", module: "compliance", action: "view" },
      { id: "compliance-audit-export", module: "compliance", action: "export" },
    ]);

    byId("compliance-crawler-run").onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/compliance/crawler/run", {});
        logTo("compliance-crawler-log", `indexed=${r.indexed}, queued=${r.queued}`);
      } catch (err) {
        logTo("compliance-crawler-log", err.error || "crawler failed");
      }
    };
    byId("compliance-crawler-status").onclick = async () => {
      try {
        const r = await apiGet("/rpc/api/compliance/crawler/status");
        logTo("compliance-crawler-log", JSON.stringify(r));
      } catch (err) {
        logTo("compliance-crawler-log", err.error || "status failed");
      }
    };
    byId("compliance-retention-status").onclick = async () => {
      try {
        const r = await apiGet("/rpc/api/compliance/retention/jobs");
        byId("compliance-retention-log").textContent = JSON.stringify(r, null, 2);
      } catch (err) {
        byId("compliance-retention-log").textContent = err.error || "retention failed";
      }
    };

    byId("compliance-delete-create").onclick = async () => {
      const ref = byId("compliance-subject-ref").value.trim();
      try {
        const r = await apiPost("/rpc/api/compliance/deletion-requests", { subject_ref: ref });
        byId("compliance-process-id").value = r.id;
        logTo("compliance-delete-log", `Created ${r.id}`);
      } catch (err) {
        logTo("compliance-delete-log", err.error || "create failed");
      }
    };
    byId("compliance-list-delete").onclick = async () => {
      try {
        const r = await apiGet("/rpc/api/compliance/deletion-requests");
        const lines = (r.requests || []).map((x) => `${x.id} | ${x.subject_ref} | ${x.status} | due=${x.due_at}`);
        byId("compliance-delete-log").textContent = lines.join("\n") || "No requests";
      } catch (err) {
        byId("compliance-delete-log").textContent = err.error || "list failed";
      }
    };
    byId("compliance-delete-process").onclick = async () => {
      const id = byId("compliance-process-id").value.trim();
      try {
        await stepUp("delete_or_reversal");
        const r = await apiPost(`/rpc/api/compliance/deletion-requests/${id}/process`, {});
        logTo("compliance-delete-log", `Processed ${id} policy=${r.policy}`);
      } catch (err) {
        logTo("compliance-delete-log", err.error || "process failed");
      }
    };

    byId("compliance-audit-load").onclick = async () => {
      const action = encodeURIComponent(byId("compliance-audit-filter").value.trim());
      const page = encodeURIComponent(byId("compliance-audit-page").value.trim() || "1");
      const limit = encodeURIComponent(byId("compliance-audit-limit").value.trim() || "50");
      try {
        const r = await apiGet(`/rpc/api/compliance/audit-logs?page=${page}&limit=${limit}&action=${action}`);
        const lines = (r.logs || []).map((l) => `${l.at} | ${l.actor} | ${l.action}`);
        byId("compliance-audit-log").textContent = lines.join("\n") || "No logs";
      } catch (err) {
        byId("compliance-audit-log").textContent = err.error || "audit failed";
      }
    };

    byId("compliance-audit-export").onclick = async () => {
      try {
        await stepUp("export");
        const text = await apiFetch("/rpc/api/compliance/audit-logs/export?format=csv&limit=500", { method: "GET", auth: true, stepUp: true });
        byId("compliance-audit-log").textContent = String(text).slice(0, 3000);
      } catch (err) {
        toast(err.error || "Export failed", "error");
      }
    };
  }

  function wireQuickButtons() {
    const j = byId("create-job-btn");
    if (j) j.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/hiring/jobs", { code: `JOB-${Date.now()}`, title: "Warehouse Associate", description: "Inbound ops", site_code: "SITE-A" });
        logTo("activity-log", `Created job ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "job failed");
      }
    };

    const t = byId("create-ticket-btn");
    if (t) t.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/support/tickets", { order_id: "ORD-1001", ticket_type: "return_and_refund", priority: "HIGH", description: "Quick ticket", business_site: "SITE-A" });
        localStorage.setItem(scopedKey(LAST_TICKET_KEY_BASE), r.id);
        logTo("activity-log", `Created ticket ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "ticket failed");
      }
    };

    const rb = byId("create-reservation-btn");
    if (rb) rb.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/inventory/reservations/order-create", { order_id: `ORD-${Date.now()}`, sku: "SKU-100", quantity: 2, site_code: "SITE-A" }, { idempotency: true });
        logTo("activity-log", `Reservation ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "reservation failed");
      }
    };
  }

  async function initRoute() {
    wireGlobal();
    if (path === "/") {
      const form = byId("login-form");
      if (form) form.addEventListener("submit", loginFlow);
      return;
    }

    const ctx = await fetchUserContext();
    if (!ctx) {
      toast("Session missing or expired, login again", "warn");
      return;
    }

    if (path === "/dashboard") {
      await initDashboard(ctx);
      wireQuickButtons();
      return;
    }
    if (path === "/hiring") return initHiring(ctx);
    if (path === "/hiring/kiosk") return initKiosk();
    if (path === "/support") return initSupport(ctx);
    if (path === "/inventory") return initInventory(ctx);
    if (path === "/compliance") return initCompliance(ctx);
  }

  initRoute();
})();

