			UPDATE support_tickets
			SET description=$2, conflict_note='overwritten by client', record_version=record_version+1, updated_at=now()
			WHERE id=$1
		`, id, req.Description)
		c.JSON(http.StatusOK, gin.H{"overwritten": true})
