		}
	}
	query += `
		ORDER BY a.created_at DESC
		LIMIT 300
	`

	rows, err := h.DB.Query(query, args...)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to load applications"})
