  async function initRoute() {
    const publicPaths = new Set(["/", "/hiring/kiosk"]);
    if (path === "/") {
      session.clearAuth();
      wireGlobal();
      const form = byId("login-form");
      if (form) form.addEventListener("submit", loginFlow);
      return;
    }

    if (publicPaths.has(path)) {
      wireGlobal();
      if (path === "/hiring/kiosk") return initKiosk();
      return;
    }

    if (!session.accessToken()) {
      window.location.replace("/");
      return;
    }

    wireGlobal();

    const ctx = await fetchUserContext();
    if (!ctx) {
      clearUserScopedCache(session.userID());
      session.clearAuth();
      window.location.replace("/");
      return;
    }

    if (path === "/dashboard") {
      await initDashboard(ctx);
      wireQuickButtons();
      return;
    }
    if (path === "/hiring") return initHiring(ctx);
    if (path === "/support") return initSupport(ctx);
    if (path === "/inventory") return initInventory(ctx);
    if (path === "/compliance") return initCompliance(ctx);
  }

  initRoute();
})();

package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
)

func TestRequireKioskToken(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/kiosk", RequireKioskToken("kiosk-secret"), func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"ok": true})
	})

	w1 := httptest.NewRecorder()
	req1 := httptest.NewRequest(http.MethodPost, "/kiosk", nil)
	r.ServeHTTP(w1, req1)
	if w1.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 for missing token, got %d", w1.Code)
	}

	w2 := httptest.NewRecorder()
	req2 := httptest.NewRequest(http.MethodPost, "/kiosk", nil)
