:root {
  --bg: #f4f5f7;
  --surface: #ffffff;
  --text: #12202b;
  --muted: #5d6b77;
  --brand: #0b5cab;
  --brand-strong: #09457f;
  --error: #be3b32;
  --border: #d7dde2;
  --radius: 12px;
  --font-sans: "Source Sans 3", "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-sans);
}

.bg-app {
  background:
    radial-gradient(circle at 10% 10%, #e2ecf8 0%, transparent 28%),
    radial-gradient(circle at 90% 0%, #d6ebe0 0%, transparent 30%),
    var(--bg);
  min-height: 100vh;
}

.text-body {
  color: var(--text);
}

.page-wrap {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: 0 8px 24px rgba(5, 25, 44, 0.08);
}

.auth-card {
  width: 100%;
  max-width: 420px;
}

.title {
  margin: 0;
  font-size: 1.6rem;
}

.subtitle {
  margin-top: 8px;
  color: var(--muted);
}

.stack {
  display: grid;
  gap: 8px;
  margin-top: 14px;
}

.label {
  font-weight: 600;
}

.input {
  height: 40px;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0 10px;
}

textarea.input,
select.input {
  height: auto;
  padding: 8px 10px;
  font: inherit;
}

.input:focus,
.btn:focus,
.ghost-btn:focus,
.nav-link:focus {
  outline: 2px solid #2f7ed0;
  outline-offset: 1px;
}

.btn,
.ghost-btn {
  min-height: 40px;
  border-radius: 10px;
  cursor: pointer;
  border: none;
  font-weight: 600;
}

.btn {
  background: var(--brand);
  color: #fff;
}

.btn:hover {
  background: var(--brand-strong);
}

.ghost-btn {
  border: 1px solid var(--border);
  background: #fff;
  padding: 0 12px;
}

.error-text {
  color: var(--error);
  min-height: 1rem;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(4px);
  position: sticky;
  top: 0;
}

.topbar-left {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.nav-link {
  text-decoration: none;
  color: var(--text);
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 0.9rem;
}

.topbar-title {
  margin: 0;
  font-size: 1.2rem;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 12px;
  padding: 12px;
}

.span-all {
  grid-column: 1 / -1;
}

.module-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
  padding: 12px;
}

.muted {
  color: var(--muted);
  font-size: 0.92rem;
  margin-top: 8px;
}

.disabled {
  opacity: 0.45;
  pointer-events: none;
}

.log {
  margin: 0;
  max-height: 220px;
  overflow: auto;
  background: #10161d;
  color: #d8f0df;
  border-radius: 8px;
  padding: 8px;
  font-size: 0.86rem;
}

