		card("Deletion Requests (Sensitive)", field("compliance-subject-ref", "Subject Ref")+`<div class="actions-row"><button id="compliance-delete-create" class="btn" type="button">Create Request</button><button id="compliance-list-delete" class="ghost-btn" type="button">List Requests</button></div>`+field("compliance-process-id", "Request ID")+`<div class="actions-row"><button id="compliance-delete-process" class="btn" type="button">Process Request</button></div><pre class="log" id="compliance-delete-log"></pre>`, `class="card span-all"`) +
		card("Audit Logs", field("compliance-audit-filter", "Action filter")+field("compliance-audit-page", "Page")+field("compliance-audit-limit", "Limit")+`<div class="actions-row"><button id="compliance-audit-load" class="ghost-btn" type="button">Load Audit Logs</button><button id="compliance-audit-export" class="btn" type="button">Export Audit Logs</button></div><pre class="log" id="compliance-audit-log"></pre>`, `class="card span-all"`) +
		`</section></main>`
	return appShell("Compliance", "compliance", body)
