  async function loginFlow(e) {
    e.preventDefault();
    const username = byId("username").value.trim();
    const password = byId("password").value;
    const err = byId("login-error");
    err.textContent = "";
    try {
      const res = await apiFetch("/rpc/login", { method: "POST", auth: false, body: { username, password } });
      const claims = parseJwt(res.access_token || "");
      const oldUser = session.userID();
      const newUser = claims.sub || "";
      if (oldUser && newUser && oldUser !== newUser) clearUserScopedCache(oldUser);
      session.setAuth(res.access_token, res.refresh_token, newUser);
      window.location.href = "/dashboard";
    } catch (ex) {
      err.textContent = ex.error || "Login failed";
    }
  }

