+		accessToken, _ := getCookieValue(r, accessCookieName)
+		if accessToken == "" {
+			http.Redirect(w, r, "/", http.StatusFound)
+			return
+		}
+
+		if validateAccessToken(r.Context(), cfg, accessToken) {
+			next.ServeHTTP(w, r)
+			return
+		}
+
+		refreshToken, _ := getCookieValue(r, refreshCookieName)
