+		w.Header().Set("Content-Type", "application/json")
+	}
+	w.WriteHeader(resp.StatusCode)
+	_, _ = w.Write(raw)
+}
+
+func proxySigned(w http.ResponseWriter, r *http.Request, target string, cfg appConfig) {
