(function () {
  const path = window.location.pathname;
  const RETRY_KEY_BASE = "offline:retry_queue";
  const SUPPORT_DRAFT_KEY_BASE = "support:draft";
  const LAST_TICKET_KEY_BASE = "support:last_ticket_id";
