  }

  function populateJobDropdown(selectId, jobs) {
    const el = byId(selectId);
    if (!el || el.tagName !== "SELECT") return;
    const prior = el.value;
    const opts = [`<option value="">Select a job</option>`].concat(
      (jobs || []).map((j) => `<option value="${j.id}">${j.code} - ${j.title}</option>`)
    );
    el.innerHTML = opts.join("");
    if (prior && (jobs || []).some((j) => j.id === prior)) {
