      populateJobDropdown("csv-job-id", [], "Loading jobs...");
      setJobDropdownMessage("manual-job-state", "Loading jobs...", "muted");
      setJobDropdownMessage("csv-job-state", "Loading jobs...", "muted");

      const result = await fetchJobsForDropdown(false);
      if (result.state === "ok" && result.jobs.length > 0) {
        populateJobDropdown("manual-job-id", result.jobs);
        populateJobDropdown("csv-job-id", result.jobs);
        setJobDropdownMessage("manual-job-state", `${result.jobs.length} job(s) available`, "muted");
        setJobDropdownMessage("csv-job-state", `${result.jobs.length} job(s) available`, "muted");
        syncJobActionState();
        return;
      }

      if (result.state === "ok" && result.jobs.length === 0) {
        populateJobDropdown("manual-job-id", [], "No jobs available");
        populateJobDropdown("csv-job-id", [], "No jobs available");
        setJobDropdownMessage("manual-job-state", "No jobs available for your scope/site", "muted");
        setJobDropdownMessage("csv-job-state", "No jobs available for your scope/site", "muted");
        logTo("hiring-jobs-log", "No jobs available for current actor scope");
