		}
	}
	query += `
		ORDER BY created_at DESC
		LIMIT 200
	`

	rows, err := h.DB.Query(query, args...)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to load jobs", "code": "JOBS_QUERY_FAILED"})
