	}
	allowed, err := h.canAccessCandidate(access, id)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "scope resolution failed"})
		return
	}
	if !allowed {
		c.JSON(http.StatusForbidden, gin.H{"error": "candidate outside scope"})
		return
