        const r = await apiPost("/rpc/api/compliance/crawler/run", {});
        logTo("compliance-crawler-log", `indexed=${r.indexed}, queued=${r.queued}`);
      } catch (err) {
        logTo("compliance-crawler-log", err.error || "crawler failed");
