      } catch (err) {
        logTo("activity-log", err.error || "job failed");
      }
    };

    const t = byId("create-ticket-btn");
    if (t) t.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/support/tickets", { order_id: "ORD-1001", ticket_type: "return_and_refund", priority: "HIGH", description: "Quick ticket", business_site: "SITE-A" });
        localStorage.setItem(scopedKey(LAST_TICKET_KEY_BASE), r.id);
        logTo("activity-log", `Created ticket ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "ticket failed");
      }
    };

    const rb = byId("create-reservation-btn");
    if (rb) rb.onclick = async () => {
      try {
        const r = await apiPost("/rpc/api/inventory/reservations/order-create", { order_id: `ORD-${Date.now()}`, sku: "SKU-100", quantity: 2, site_code: "SITE-A" }, { idempotency: true });
        logTo("activity-log", `Reservation ${r.id}`);
      } catch (err) {
        logTo("activity-log", err.error || "reservation failed");
      }
    };
  }

  async function initRoute() {
    const publicPaths = new Set(["/", "/hiring/kiosk"]);
    if (path === "/") {
      session.clearAuth();
      wireGlobal();
      const form = byId("login-form");
      if (form) form.addEventListener("submit", loginFlow);
      return;
    }

    if (publicPaths.has(path)) {
      wireGlobal();
      if (path === "/hiring/kiosk") return initKiosk();
      return;
    }

    wireGlobal();

    const ctx = await fetchUserContext();
    if (!ctx) {
      clearUserScopedCache(session.userID());
      session.clearAuth();
      window.location.replace("/");
      return;
    }

    if (path === "/dashboard") {
      await initDashboard(ctx);
      wireQuickButtons();
      return;
    }
    if (path === "/hiring") return initHiring(ctx);
    if (path === "/support") return initSupport(ctx);
    if (path === "/inventory") return initInventory(ctx);
    if (path === "/compliance") return initCompliance(ctx);
  }

  initRoute();
})();

