    async function refreshJobDropdowns() {
      setJobActionEnabled(false);
      populateJobDropdown("manual-job-id", [], "Loading jobs...");
      populateJobDropdown("csv-job-id", [], "Loading jobs...");
      setJobDropdownMessage("manual-job-state", "Loading jobs...", "muted");
      setJobDropdownMessage("csv-job-state", "Loading jobs...", "muted");

      const result = await fetchJobsForDropdown(false);
      if (result.state === "ok" && result.jobs.length > 0) {
        populateJobDropdown("manual-job-id", result.jobs);
        populateJobDropdown("csv-job-id", result.jobs);
        setJobDropdownMessage("manual-job-state", `${result.jobs.length} job(s) available`, "muted");
        setJobDropdownMessage("csv-job-state", `${result.jobs.length} job(s) available`, "muted");
        syncJobActionState();
        return;
      }

      if (result.state === "ok" && result.jobs.length === 0) {
        populateJobDropdown("manual-job-id", [], "No jobs available");
        populateJobDropdown("csv-job-id", [], "No jobs available");
        setJobDropdownMessage("manual-job-state", "No jobs available for your scope/site", "muted");
        setJobDropdownMessage("csv-job-state", "No jobs available for your scope/site", "muted");
        logTo("hiring-jobs-log", "No jobs available for current actor scope");
        return;
      }

      if (result.state === "forbidden") {
        populateJobDropdown("manual-job-id", [], "Access denied to job list");
        populateJobDropdown("csv-job-id", [], "Access denied to job list");
        setJobDropdownMessage("manual-job-state", "Access denied to job list", "error");
        setJobDropdownMessage("csv-job-state", "Access denied to job list", "error");
        logTo("hiring-jobs-log", `Access denied while loading jobs: ${result.error}`);
        return;
      }

      if (result.state === "unauthorized") {
        populateJobDropdown("manual-job-id", [], "Access denied to job list");
        populateJobDropdown("csv-job-id", [], "Access denied to job list");
        setJobDropdownMessage("manual-job-state", "Session expired while loading jobs", "error");
        setJobDropdownMessage("csv-job-state", "Session expired while loading jobs", "error");
        logTo("hiring-jobs-log", `Unauthorized while loading jobs: ${result.error}`);
        return;
      }

      populateJobDropdown("manual-job-id", [], "Failed to load jobs (Retry)");
      populateJobDropdown("csv-job-id", [], "Failed to load jobs (Retry)");
      setJobDropdownMessage("manual-job-state", "Failed to load jobs. Retry.", "error");
      setJobDropdownMessage("csv-job-state", "Failed to load jobs. Retry.", "error");
      logTo("hiring-jobs-log", `Failed to load jobs: ${result.error}`);
    }

