    byId("support-save-draft").onclick = () => {
      localStorage.setItem(scopedKey(SUPPORT_DRAFT_KEY_BASE), JSON.stringify({
        order_id: byId("support-order-id").value,
        ticket_type: byId("support-ticket-type").value,
        priority: byId("support-priority").value,
        description: byId("support-description").value,
      }));
      setStatusBadge("support-draft-status", "Draft saved", "info");
      toast("Draft saved", "ok");
    };

    byId("support-restore-draft").onclick = () => {
      try {
        const d = JSON.parse(localStorage.getItem(scopedKey(SUPPORT_DRAFT_KEY_BASE)) || "{}");
        byId("support-order-id").value = d.order_id || "";
        byId("support-ticket-type").value = d.ticket_type || "return_and_refund";
        byId("support-priority").value = d.priority || "STANDARD";
        byId("support-description").value = d.description || "";
        setStatusBadge("support-draft-status", "Draft restored", "ok");
      } catch {
        setStatusBadge("support-draft-status", "No valid draft", "warn");
      }
    };

    byId("support-refresh-list").onclick = async () => {
      try {
        const list = await apiGet("/rpc/api/support/tickets");
        const lines = (list.tickets || []).map((t) => `${t.id} | ${t.status} | SLA=${t.sla_seconds}s | escalated=${t.escalated}`);
        byId("support-ticket-list-log").textContent = lines.join("\n") || "No tickets";
      } catch (err) {
        byId("support-ticket-list-log").textContent = err.error || "Failed to load tickets";
      }
    };

    byId("support-add-attachment").onclick = async () => {
      const ticketID = localStorage.getItem(scopedKey(LAST_TICKET_KEY_BASE)) || prompt("Ticket ID");
      if (!ticketID) return;
      const input = byId("support-attach-file");
      const file = input.files && input.files[0];
      if (!file) return logTo("support-attach-log", "Select a file first");
      const allowed = ["image/jpeg", "image/png", "application/pdf"];
      if (!allowed.includes(file.type)) return logTo("support-attach-log", "Only JPG/PNG/PDF accepted");
      if (file.size > 10 * 1024 * 1024) return logTo("support-attach-log", "File exceeds 10MB");
      const hash = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
      const checksum = Array.from(new Uint8Array(hash)).map((b) => b.toString(16).padStart(2, "0")).join("");
      try {
        await apiPost(`/rpc/api/support/tickets/${ticketID}/attachments`, {
          file_name: file.name,
          mime_type: file.type,
          size_mb: Math.max(1, Math.ceil(file.size / (1024 * 1024))),
          checksum,
        });
        logTo("support-attach-log", `Attachment accepted ${file.name}`);
      } catch (err) {
        logTo("support-attach-log", `Attachment failed ${err.error || err.status}`);
      }
    };

    byId("support-update-submit").onclick = async () => {
      const ticketID = byId("support-update-ticket-id").value.trim();
      const version = Number(byId("support-update-version").value || "1");
      const description = byId("support-update-description").value;
      try {
        const res = await apiPut(`/rpc/api/support/tickets/${ticketID}`, { description, record_version: version });
        logTo("support-conflict-log", `Update succeeded version=${res.record_version}`);
      } catch (err) {
        if (err.status !== 409) {
          logTo("support-conflict-log", `Update failed: ${err.error || err.status}`);
          return;
        }
        const choice = (prompt("Version conflict. Choose merge, overwrite, or discard.", "merge") || "discard").toLowerCase();
        if (choice === "discard") {
          logTo("support-conflict-log", "Conflict discarded. Latest server version kept.");
          return;
        }
        try {
          const r = await apiPost(`/rpc/api/support/tickets/${ticketID}/conflict-resolve`, {
            mode: choice,
            current_version: err.current_version || version,
            expected_version: version,
            description,
          });
          logTo("support-conflict-log", `Conflict resolved (${choice}): ${JSON.stringify(r)}`);
        } catch (e2) {
          logTo("support-conflict-log", `Conflict resolution failed: ${e2.error || e2.status}`);
        }
      }
    };
  }

