  async function fetchJobsForDropdown(allowPublicFallback) {
    try {
      const res = await apiGet("/rpc/api/hiring/jobs");
      return { jobs: res.jobs || [], state: "ok", error: "" };
    } catch (err) {
      if (err.status === 401) {
        return { jobs: [], state: "unauthorized", error: err.error || "Session expired" };
      }
      if (err.status === 403) {
        try {
          const res = await apiGet("/rpc/api/hiring/jobs/for-intake");
          return { jobs: res.jobs || [], state: "ok", error: "" };
        } catch (createErr) {
          if (createErr.status === 401) {
            return { jobs: [], state: "unauthorized", error: createErr.error || "Session expired" };
          }
          return { jobs: [], state: "forbidden", error: createErr.error || err.error || "Access denied" };
        }
      }
      if (allowPublicFallback) {
        try {
          const res = await apiFetch("/rpc/kiosk/jobs", { method: "GET", auth: false });
          return { jobs: res.jobs || [], state: "ok", error: "" };
        } catch (kioskErr) {
          return { jobs: [], state: "error", error: kioskErr.error || `HTTP ${kioskErr.status || 500}` };
        }
      }
      return { jobs: [], state: "error", error: err.error || `HTTP ${err.status || 500}` };
    }
  }

  function showModuleUnauthorized(moduleName) {
    const root = document.querySelector("main.page-wrap, main.module-grid, main.dashboard-grid");
