function applyActionGates(perms, mapping) {
  mapping.forEach((m) => {
    const el = byId(m.id);
    const allowed = can(perms, m.module, m.action);
    setVisibility(el, allowed, `${m.module}:${m.action} required`);
  });
}

function logTo(id, msg) {
  const el = byId(id);
