		card("Cycle Count", field("cycle-wh", "Warehouse")+field("cycle-sku", "SKU")+field("cycle-counted", "Counted Qty")+field("cycle-reason", "Reason")+`<div class="actions-row"><button class="btn" id="inventory-cycle-submit" type="button">Submit Cycle Count</button></div><pre class="log" id="inventory-cycle-log"></pre>`, ``) +
		card("Balances + Reservations", `<div class="actions-row"><button id="inventory-refresh-balances" class="ghost-btn" type="button">Refresh Balances</button><button id="inventory-create-reservation" class="btn" type="button">Create Reservation</button><button id="inventory-refresh-reservations" class="ghost-btn" type="button">Refresh Reservations</button></div><pre class="log" id="inventory-balances-log"></pre><pre class="log" id="inventory-reservations-log"></pre>`, `class="card span-all"`) +
		`</section></main>`
	return appShell("Inventory", "inventory", body)
}

