async function refreshJobDropdowns() {
  const hasManual = !!byId("manual-job-id");
  const hasCSV = !!byId("csv-job-id");
  if (!hasManual && !hasCSV) return;
  const result = await fetchJobsForDropdown(false);
  if (result.state === "ok") {
    if (hasManual) populateJobDropdown("manual-job-id", result.jobs || []);
    if (hasCSV) populateJobDropdown("csv-job-id", result.jobs || []);
    return;
  }
  if (hasManual) populateJobDropdown("manual-job-id", [], "Unable to load jobs");
  if (hasCSV) populateJobDropdown("csv-job-id", [], "Unable to load jobs");
  logTo("hiring-jobs-log", `Job dropdown load failed: ${result.error || result.state}`);
}

